### 2. The Code (`MainActivity.kt`)

This single-file solution uses `NavController` to switch between a dashboard and a transfer screen.

```kotlin
package com.example.minimalbank

import android.os.Bundle
import androidx.activity.ComponentActivity
import androidx.activity.compose.setContent
import androidx.compose.foundation.layout.*
import androidx.compose.material3.*
import androidx.compose.runtime.*
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.unit.dp
import androidx.navigation.compose.*

class MainActivity : ComponentActivity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContent {
            val navController = rememberNavController()
            var balance by remember { mutableStateOf(1250.50) }

            NavHost(navController, startDestination = "home") {
                composable("home") {
                    HomeScreen(balance) { navController.navigate("transfer") }
                }
                composable("transfer") {
                    TransferScreen(onTransfer = { amount ->
                        balance -= amount
                        navController.popBackStack()
                    })
                }
            }
        }
    }
}

@Composable
fun HomeScreen(balance: Double, onNavigate: () -> Unit) {
    Column(Modifier.fillMaxSize().padding(16.dp), horizontalAlignment = Alignment.CenterHorizontally) {
        Text("My Bank Account", style = MaterialTheme.typography.headlineMedium)
        Spacer(Modifier.height(20.dp))
        Text("Balance: $$balance", style = MaterialTheme.typography.displaySmall)
        Spacer(Modifier.height(20.dp))
        Button(onClick = onNavigate) { Text("Transfer Funds") }
    }
}

@Composable
fun TransferScreen(onTransfer: (Double) -> Unit) {
    var amount by remember { mutableStateOf("") }
    Column(Modifier.padding(16.dp)) {
        OutlinedTextField(value = amount, onValueChange = { amount = it }, label = { Text("Amount") })
        Button(onClick = { onTransfer(amount.toDoubleOrNull() ?: 0.0) }) {
            Text("Confirm Transfer")
        }
    }
}
```

