import androidx.lifecycle.MutableLiveData
import androidx.lifecycle.ViewModel

class BankingViewModel : ViewModel() {
    val balance = MutableLiveData(1000.0) // Starting balance

    fun transferMoney(amount: Double): Boolean {
        val current = balance.value ?: 0.0
