### 2. The Sync Logic
You need to listen for network changes and trigger a push/pull sync.

```javascript
import NetInfo from "@react-native-community/netinfo";
import { synchronize } from "@nozbe/watermelondb/sync";

async function syncData() {
  const isConnected = (await NetInfo.fetch()).isConnected;

  if (!isConnected) return;

  await synchronize({
    database,
    pullChanges: async ({ lastPulledAt }) => {
      const response = await fetch(`https://api.myapp.com/sync?last_pulled=${lastPulledAt}`);
      return await response.json();
    },
    pushChanges: async ({ changes }) => {
      await fetch(`https://api.myapp.com/sync`, {
        method: 'POST',
        body: JSON.stringify(changes),
      });
    },
  });
}

// Listen for network reconnection
NetInfo.addEventListener(state => {
  if (state.isConnected) syncData();
});
```

