        await db.execute("UPDATE surveys SET sync_status = 'synced' WHERE id = ?", [record.id]);
      }
    } catch (error) {
      console.error("Sync failed, will retry later:", error);
      // Keep as 'pending' to try again on next network event
    }
  }
}
