### 2. The Sync Engine (`sync.js`)
This function handles the heavy lifting: pushing local changes to the server and pulling server updates.

```javascript
import { synchronize } from '@nozbe/watermelon-db/sync'

export async function syncDatabase(database) {
  await synchronize({
    database,
    pullChanges: async ({ lastPulledAt }) => {
      const response = await fetch(`/api/sync?last_pulled=${lastPulledAt}`);
      const { changes, timestamp } = await response.json();
      return { changes, timestamp };
    },
    pushChanges: async ({ changes, lastPulledAt }) => {
      await fetch(`/api/sync`, {
        method: 'POST',
        body: JSON.stringify({ changes }),
      });
    },
  });
}
```

