### 1. The Data Model (`schema.js`)
Define your survey data schema. WatermelonDB uses this to create the local SQLite tables.

```javascript
import { appSchema, tableSchema } from '@nozbe/watermelondb'

export default appSchema({
  version: 1,
  tables: [
    tableSchema({
      name: 'surveys',
      columns: [
        { name: 'site_name', type: 'string' },
        { name: 'latitude', type: 'number' },
        { name: 'longitude', type: 'number' },
        { name: 'status', type: 'string' }, // 'synced' or 'pending'
      ]
    })
  ]
})
```

### 2. Saving Data Offline
When a surveyor saves a record, we write it to the local database immediately.

```javascript
const saveSurvey = async (data) => {
  await database.write(async () => {
    await database.get('surveys').create(survey => {
      survey.site_name = data.name;
      survey.status = 'pending';
    });
  });
};
```

### 3. The Sync Logic
This function finds all records marked as `pending` and pushes them to your server.

```javascript
import NetInfo from "@react-native-community/netinfo";

const syncData = async () => {
  const state = await NetInfo.fetch();
  if (!state.isConnected) return;

  const pendingSurveys = await database.get('surveys')
    .query(Q.where('status', 'pending'))
    .fetch();

  for (const survey of pendingSurveys) {
    try {
      const response = await fetch('https://api.yoursurvey.com/upload', {
        method: 'POST',
        body: JSON.stringify(survey),
      });

      if (response.ok) {
        await database.write(async () => {
          await survey.update(s => { s.status = 'synced' });
        });
      }
    } catch (e) {
      console.log("Sync failed, will retry later");
    }
  }
};
```

### 4. Background Sync Listener
Listen for connectivity changes to trigger the sync automatically.

```javascript
import { useEffect } from 'react';
import NetInfo from "@react-native-netinfo/netinfo";

export const useSyncManager = () => {
  useEffect(() => {
    const unsubscribe = NetInfo.addEventListener(state => {
      if (state.isConnected) {
        console.log("Back online! Syncing...");
        syncData();
      }
    });

    return () => unsubscribe();
  }, []);
};
```

