### 3. The Offline-First Hook
This hook saves data locally immediately, then attempts to push to the server if the device is online.

```javascript
import { useNetInfo } from "@react-native-community/netinfo";
import { database } from "./database";

export const useSaveSurvey = () => {
  const netInfo = useNetInfo();

  const saveSurvey = async (data) => {
    // 1. Always save to local DB first
    const newSurvey = await database.write(async () => {
      return await database.get('surveys').create(s => {
        s.survey_data = JSON.stringify(data);
        s.status = netInfo.isConnected ? 'synced' : 'pending';
      });
    });

    // 2. If online, trigger sync
    if (netInfo.isConnected) {
      syncSurvey(newSurvey);
    }
  };

  return { saveSurvey };
};
```

