### 4. The Sync Manager
This logic runs when the app detects an internet connection, processing the "pending" queue.

```javascript
import { Q } from '@nozbe/watermelondb';

const syncPendingSurveys = async () => {
  const pending = await database.get('surveys')
    .query(Q.where('status', 'pending'))
    .fetch();

  for (const survey of pending) {
    try {
      const response = await fetch('https://api.yourservice.com/surveys', {
        method: 'POST',
        body: survey.survey_data
      });

      if (response.ok) {
        await database.write(async () => {
          await survey.update(s => { s.status = 'synced' });
        });
      }
    } catch (e) {
      console.log("Sync failed, will retry later");
    }
  }
};
```

