### 3. The Sync Hook (React Native)
This hook manages the logic of checking connectivity and uploading data.

```javascript
import { useEffect } from 'react';
import NetInfo from "@react-native-community/netinfo";
import { db } from './database'; // Your SQLite wrapper

export const useSync = () => {
  useEffect(() => {
    const unsubscribe = NetInfo.addEventListener(state => {
      if (state.isConnected) {
        syncData();
      }
    });
    return () => unsubscribe();
  }, []);

  const syncData = async () => {
    // 1. Fetch all records where is_synced = 0
    const unsynced = await db.executeSql('SELECT * FROM surveys WHERE is_synced = 0');

    for (const record of unsynced) {
      try {
        // 2. Push to your API
        await fetch('https://api.yoursurvey.com/submit', {
          method: 'POST',
          body: JSON.stringify(record)
        });

        // 3. Update local record to synced
        await db.executeSql('UPDATE surveys SET is_synced = 1 WHERE id = ?', [record.id]);
      } catch (err) {
        console.error("Failed to sync record", record.id);
      }
    }
  };
};
```

### 4. Saving Data (UI Component)
When the user hits "Submit," you save to the local database regardless of network status.

