const handleSave = async (surveyData) => {
  const record = { ...surveyData, id: generateUUID(), is_synced: 0 };

  // Save to SQLite
  await db.executeSql(
    'INSERT INTO surveys (id, site_name, is_synced) VALUES (?, ?, ?)',
    [record.id, record.site_name, 0]
  );

  Alert.alert("Saved locally!");

  // Trigger sync attempt immediately if online
  const net = await NetInfo.fetch();
  if (net.isConnected) syncData();
};
```

