### 1. Define the Data Model
This represents a field survey entry.

```kotlin
@Entity(tableName = "surveys")
data class Survey(
    @PrimaryKey val id: String = UUID.randomUUID().toString(),
    val locationName: String,
    val notes: String,
    val isSynced: Boolean = false // Flag to track sync status
)
```

### 2. Local Database (Room)
The DAO provides a query to fetch only unsynced data.

```kotlin
@Dao
interface SurveyDao {
    @Insert(onConflict = OnConflictStrategy.REPLACE)
    suspend fun insert(survey: Survey)

    @Query("SELECT * FROM surveys WHERE isSynced = 0")
    suspend fun getUnsyncedSurveys(): List<Survey>

    @Update
    suspend fun update(survey: Survey)
}
```

### 3. Sync Worker
`WorkManager` is the best tool for this because it automatically handles retries and persistence across app restarts.

```kotlin
class SyncWorker(context: Context, params: WorkerParameters) : CoroutineWorker(context, params) {
    override suspend fun doWork(): Result {
        val db = AppDatabase.getDatabase(applicationContext)
        val unsynced = db.surveyDao().getUnsyncedSurveys()

        return try {
            for (survey in unsynced) {
                // API Call to your server
                val success = apiService.uploadSurvey(survey) 
                if (success) {
                    db.surveyDao().update(survey.copy(isSynced = true))
                }
            }
            Result.success()
        } catch (e: Exception) {
            Result.retry() // Retries automatically when network is back
        }
    }
}
```

### 4. Scheduling the Sync
Trigger the sync whenever the device regains internet access.

```kotlin
fun scheduleSync(context: Context) {
    val constraints = Constraints.Builder()
        .setRequiredNetworkType(NetworkType.CONNECTED)
        .build()

    val syncRequest = PeriodicWorkRequestBuilder<SyncWorker>(1, TimeUnit.HOURS)
        .setConstraints(constraints)
        .build()

    WorkManager.getInstance(context).enqueueUniquePeriodicWork(
        "survey_sync",
        ExistingPeriodicWorkPolicy.KEEP,
        syncRequest
    )
}
```

### 5. UI Layer Implementation
When the user clicks "Submit," write to the local DB immediately.

```kotlin
fun onSaveSurvey(survey: Survey) {
    viewModelScope.launch {
        // 1. Save locally
        repository.insert(survey)

        // 2. Trigger a one-time sync attempt immediately
        val oneTimeSync = OneTimeWorkRequestBuilder<SyncWorker>()
            .setConstraints(Constraints(requiredNetworkType = NetworkType.CONNECTED))
            .build()
        WorkManager.getInstance(context).enqueue(oneTimeSync)
    }
}
```

