This script handles writing to IndexedDB and automatically pushing data when the browser detects a connection.

```javascript
const dbPromise = idb.openDB('survey-db', 1, {
  upgrade(db) { db.createObjectStore('queue', { autoIncrement: true }); }
});

// 1. Save data locally
async function saveData() {
  const data = document.getElementById('surveyInput').value;
  const db = await dbPromise;
  await db.add('queue', { data, timestamp: Date.now() });
  console.log("Saved locally");
  syncData(); // Try to sync immediately
}

// 2. Sync logic
async function syncData() {
  if (!navigator.onLine) return;

  const db = await dbPromise;
  const tx = db.transaction('queue', 'readwrite');
  const store = tx.objectStore('queue');
  const items = await store.getAll();

  for (const item of items) {
    try {
      // Simulate API call
      await fetch('/api/survey', { method: 'POST', body: JSON.stringify(item) });
      await store.delete(item.id); // Remove from queue only if success
    } catch (e) {
      console.error("Sync failed, will retry later");
      break; 
    }
  }
}

// 3. Listen for reconnection
window.addEventListener('online', () => {
  document.getElementById('status').innerText = "Status: Online";
  syncData();
});

window.addEventListener('offline', () => {
  document.getElementById('status').innerText = "Status: Offline";
});
```

