  e.preventDefault();
  const data = { name: document.getElementById('name').value, ts: Date.now() };

  await (await dbPromise).add('entries', data);
  syncData();
};

// Sync logic
async function syncData() {
  if (!navigator.onLine) {
    document.getElementById('status').innerText = "Offline: Data saved locally.";
    return;
  }

  const db = await dbPromise;
  const tx = db.transaction('entries', 'readwrite');
  const entries = await tx.store.getAll();

  for (const entry of entries) {
    try {
      await fetch('/api/survey', { method: 'POST', body: JSON.stringify(entry) });
      await tx.store.delete(entry.id); // Remove if successful
    } catch (e) { console.error("Sync failed", e); }
  }
  document.getElementById('status').innerText = "Synced!";
}

window.addEventListener('online', syncData);
```

### 3. The Service Worker (`sw.js`)
This makes the app work even if the user closes and reopens the browser while offline.

```javascript
const CACHE = 'survey-v1';
self.addEventListener('install', (e) => {
  e.waitUntil(caches.open(CACHE).then(c => c.addAll(['/', '/index.html', '/app.js'])));
});

self.addEventListener('fetch', (e) => {
  // Network-first strategy
  e.respondWith(
    fetch(e.request).catch(() => caches.match(e.request))
  );
});
```

