### 2. Real-Time Chat Implementation
We use `react-native-gifted-chat` because it handles the complex UI of chat bubbles and input fields out of the box.

```javascript
// screens/ChatScreen.js
import React, { useState, useEffect, useCallback } from 'react';
import { GiftedChat } from 'react-native-gifted-chat';
import { collection, addDoc, query, orderBy, onSnapshot } from 'firebase/firestore';
import { db } from '../firebaseConfig';

export default function ChatScreen() {
  const [messages, setMessages] = useState([]);

  useEffect(() => {
    // Real-time listener for new messages
    const q = query(collection(db, 'chats'), orderBy('createdAt', 'desc'));
    const unsubscribe = onSnapshot(q, (snapshot) => {
      setMessages(snapshot.docs.map(doc => ({
        _id: doc.id,
        ...doc.data(),
        createdAt: doc.data().createdAt.toDate(),
      })));
    });
    return unsubscribe;
  }, []);

  const onSend = useCallback((messages = []) => {
    const { _id, createdAt, text, user } = messages[0];
    addDoc(collection(db, 'chats'), { _id, createdAt, text, user });
  }, []);

  return <GiftedChat messages={messages} onSend={onSend} user={{ _id: 1 }} />;
}
```

### 3. Real-Time Notifications
To trigger notifications when a new message arrives, you need a **Firebase Cloud Function**. This runs on the server whenever a message is added to the database.

```javascript
// functions/index.js
const functions = require('firebase-functions');
const admin = require('firebase-admin');
admin.initializeApp();

exports.sendNotification = functions.firestore
  .document('chats/{messageId}')
  .onCreate((snap, context) => {
    const message = snap.data();
    const payload = {
      notification: {
        title: 'New Message',
        body: message.text,
      }
    };
    // Send to specific device token
    return admin.messaging().sendToTopic('all', payload);
  });
```

