  // Simulate Real-time Data Feed
  useEffect(() => {
    const interval = setInterval(() => {
      const newVal = Math.floor(Math.random() * 50);
      const newTime = new Date().toLocaleTimeString().slice(-8);

      setDataPoints(prev => [...prev.slice(1), newVal]);
      setLabels(prev => [...prev.slice(1), newTime]);
    }, 3000);
    return () => clearInterval(interval);
  }, []);

  // Form Handler
  const handleSubmit = (e) => {
    e.preventDefault();
    alert(`Data point submitted: ${inputValue}`);
    setDataPoints(prev => [...prev.slice(1), parseInt(inputValue)]);
    setInputValue('');
  };

  const data = {
    labels,
    datasets: [{ label: 'Live Sensor Data', data: dataPoints, borderColor: 'rgb(75, 192, 192)', tension: 0.1 }]
  };

  return (
    <div style={{ padding: '20px', maxWidth: '800px', margin: 'auto' }}>
      <h1>Real-Time Dashboard</h1>

      <div style={{ height: '300px' }}>
        <Line data={data} options={{ maintainAspectRatio: false }} />
      </div>

      <form onSubmit={handleSubmit} style={{ marginTop: '20px' }}>
        <input 
          type="number" 
          value={inputValue} 
          onChange={(e) => setInputValue(e.target.value)}
          placeholder="Inject custom value"
          required
        />
        <button type="submit">Update Chart</button>
      </form>
    </div>
  );
}
```

### Key Components of this Solution:

1.  **State Management (`useState`):**
    *   `dataPoints` and `labels` act as the "source of truth." When these update, the chart re-renders automatically.
2.  **Real-time Simulation (`useEffect`):**
    *   The `setInterval` function mimics an API connection (like a WebSocket). It pushes new data into the state every 3 seconds and trims the old data to keep the chart clean.
3.  **Visualization (`Chart.js`):**
    *   We use `react-chartjs-2`, which is a lightweight wrapper. It handles the canvas rendering, animations, and tooltips automatically.
4.  **Form Handling:**
    *   Standard React controlled inputs (`onChange`) capture the user's input.
    *   The `handleSubmit` function prevents the default browser reload and allows you to inject manual data into the visualization stream.

