            <button type="submit">Update Chart</button>
        </form>
    </div>

    <div style="width: 600px;">
        <canvas id="myChart"></canvas>
    </div>

    <script>
        const ctx = document.getElementById('myChart').getContext('2d');
        const chart = new Chart(ctx, {
            type: 'line',
            data: {
                labels: ['1', '2', '3', '4', '5'],
                datasets: [{ label: 'Real-time Stats', data: [10, 20, 15, 25, 30], borderColor: 'blue' }]
            }
        });

        // 1. Form Handling
        document.getElementById('dataForm').addEventListener('submit', (e) => {
            e.preventDefault();
            const newVal = document.getElementById('val').value;
            chart.data.datasets[0].data.push(newVal);
            chart.data.labels.push(chart.data.labels.length + 1);
            chart.update();
        });

        // 2. Real-time Simulation (Automatic updates)
        setInterval(() => {
            const randomVal = Math.floor(Math.random() * 50);
            chart.data.datasets[0].data.push(randomVal);
            chart.data.labels.push(chart.data.labels.length + 1);

            // Keep chart clean by removing old points
            if(chart.data.labels.length > 10) {
                chart.data.labels.shift();
                chart.data.datasets[0].data.shift();
            }
            chart.update();
        }, 3000);
    </script>
</body>
</html>
