    <div id="tooltip" class="tooltip"></div>
    <canvas id="chart"></canvas>

    <script>
        const canvas = document.getElementById('chart');
        const ctx = canvas.getContext('2d');
        let width, height;

        // Mock Data: 100 stocks
        let data = Array.from({length: 100}, (_, i) => ({
            symbol: `STK${i}`,
            price: Math.random() * 500,
            change: (Math.random() - 0.5) * 10
        }));

        let transform = d3.zoomIdentity;

        function resize() {
            width = canvas.width = window.innerWidth;
            height = canvas.height = window.innerHeight;
            draw();
        }

        function draw() {
            ctx.clearRect(0, 0, width, height);
            ctx.save();
            ctx.translate(transform.x, transform.y);
            ctx.scale(transform.k, transform.k);

            // Simple Grid Layout
            const cols = 10;
            const size = 80;
            data.forEach((d, i) => {
                const x = (i % cols) * (size + 5);
                const y = Math.floor(i / cols) * (size + 5);

                ctx.fillStyle = d.change >= 0 ? `rgb(0, ${100 + d.change*10}, 0)` : `rgb(${100 + Math.abs(d.change)*10}, 0, 0)`;
                ctx.fillRect(x, y, size, size);
                ctx.fillStyle = 'white';
                ctx.fillText(d.symbol, x + 5, y + 20);
                ctx.fillText(d.change.toFixed(2) + '%', x + 5, y + 40);
            });
            ctx.restore();
        }

        // Zoom/Pan logic
        const zoom = d3.zoom().on('zoom', (event) => {
            transform = event.transform;
            draw();
        });
        d3.select(canvas).call(zoom);

        // Real-time update simulation
        setInterval(() => {
            data.forEach(d => d.change += (Math.random() - 0.5));
            draw();
        }, 2000);

        window.addEventListener('resize', resize);
        resize();
    </script>
</body>
</html>
```

### Key Features Explained:

1.  **Canvas Rendering**: Instead of creating hundreds of DOM elements (which would lag during zoom), we draw directly to a `<canvas>`. This allows for thousands of stocks to be rendered smoothly.
2.  **D3 Zoom/Pan**: We attach `d3.zoom()` to the canvas. It tracks the `transform` state (x, y, and scale), which we then apply to the `ctx` context before every draw call.
3.  **Real-time Simulation**: The `setInterval` function updates the `change` property of the data objects every 2 seconds and triggers a re-draw, simulating a live market feed.
4.  **Performance**: The `draw()` function is modular. You can call it whenever the data changes or whenever the user interacts with the zoom.

