        .append("div")
        .attr("class", "node")
        .merge(nodes)
        .style("left", d => d.x0 + "px")
        .style("top", d => d.y0 + "px")
        .style("width", d => (d.x1 - d.x0) + "px")
        .style("height", d => (d.y1 - d.y0) + "px")
        .style("background", d => d.data.change > 0 ? "green" : "red")
        .html(d => `<div class="node-label">${d.data.name}<br>${(d.data.change*100).toFixed(2)}%</div>`);
}

// Simulate Real-time WebSocket updates
setInterval(() => {
    data.children.forEach(stock => {
        stock.change += (Math.random() - 0.5) * 0.02;
    });
    updateHeatmap(data);
}, 2000);
```

