```html
<!DOCTYPE html>
<html>
<head>
    <script src="https://d3js.org/d3.v7.min.js"></script>
    <style>
        .node { border: 1px solid white; cursor: pointer; display: flex; align-items: center; justify-content: center; color: white; font-size: 10px; overflow: hidden; position: absolute; }
        #chart { width: 100vw; height: 90vh; position: relative; overflow: hidden; }
    </style>
</head>
<body>
    <div id="chart"></div>

    <script>
        const width = window.innerWidth;
        const height = window.innerHeight * 0.9;
        const svg = d3.select("#chart").append("svg").attr("width", width).attr("height", height);

        // Initial Dummy Data
        let data = { name: "Market", children: [
            { name: "AAPL", value: 100, change: 0.02 },
            { name: "GOOGL", value: 80, change: -0.015 },
            { name: "MSFT", value: 90, change: 0.04 },
            { name: "AMZN", value: 70, change: -0.03 }
        ]};

        function update() {
            const root = d3.hierarchy(data).sum(d => d.value);
            d3.treemap().size([width, height]).padding(1)(root);

            const nodes = svg.selectAll(".node").data(root.leaves(), d => d.data.name);

            nodes.join("foreignObject")
                .attr("class", "node")
                .attr("x", d => d.x0).attr("y", d => d.y0)
                .attr("width", d => d.x1 - d.x0).attr("height", d => d.y1 - d.y0)
                .style("background", d => d.data.change >= 0 ? "green" : "red")
                .html(d => `<div>${d.data.name}<br>${(d.data.change*100).toFixed(1)}%</div>`);
        }

        // Add Zoom/Pan
        const zoom = d3.zoom().scaleExtent([1, 8]).on("zoom", (e) => {
            svg.attr("transform", e.transform);
        });
        svg.call(zoom);

        // Simulate Real-time Updates
        setInterval(() => {
            data.children.forEach(d => d.change += (Math.random() - 0.5) * 0.02);
            update();
        }, 2000);

        update();
    </script>
</body>
</html>
```

