            .attr("class", "cell")
            .attr("width", d => d.x1 - d.x0)
            .attr("height", d => d.y1 - d.y0)
            .attr("fill", d => color(d.data.value));

        cells.append("text")
            .attr("class", "label")
            .attr("x", 5).attr("y", 15)
            .text(d => `${d.data.symbol} (${d.data.value.toFixed(1)}%)`);

        // Zoom & Pan behavior
        const zoom = d3.zoom().scaleExtent([1, 8]).on("zoom", (event) => {
            g.attr("transform", event.transform);
        });
