```javascript
const canvas = document.getElementById('heatmap');
const ctx = canvas.getContext('2d');
let width, height;

// Mock Data: Stocks with price change percentage
let stocks = Array.from({ length: 50 }, (_, i) => ({
  id: i,
  change: (Math.random() * 10) - 5, // -5% to +5%
  name: `STK${i}`
}));

// D3 Zoom setup
const zoom = d3.zoom()
  .scaleExtent([1, 8])
  .on('zoom', (event) => render(event.transform));

d3.select(canvas).call(zoom);

function render(transform) {
  width = window.innerWidth;
  height = window.innerHeight;
  canvas.width = width;
  canvas.height = height;

  ctx.clearRect(0, 0, width, height);
  ctx.save();
  ctx.translate(transform.x, transform.y);
  ctx.scale(transform.k, transform.k);

  // Draw Grid
  const cols = 7;
  const cellW = width / cols;
  const cellH = 100;

  stocks.forEach((d, i) => {
    const x = (i % cols) * cellW;
    const y = Math.floor(i / cols) * cellH;

    // Color based on performance
    ctx.fillStyle = d.change >= 0 ? `rgb(0, ${100 + d.change * 20}, 0)` : `rgb(${100 - d.change * 20}, 0, 0)`;
    ctx.fillRect(x + 2, y + 2, cellW - 4, cellH - 4);

    // Label
    ctx.fillStyle = "white";
    ctx.fillText(d.name, x + 10, y + 20);
    ctx.fillText(d.change.toFixed(2) + "%", x + 10, y + 40);
  });

  ctx.restore();
}

// Initial render
render(d3.zoomIdentity);

// Real-time update simulation
setInterval(() => {
  stocks.forEach(s => s.change += (Math.random() - 0.5));
  render(d3.zoomTransform(canvas));
}, 2000);
```

