    .data(data)
    .enter().append("rect")
    .attr("class", "cell")
    .attr("x", (d, i) => (i % cols) * cellSize)
    .attr("y", (d, i) => Math.floor(i / cols) * cellSize)
    .attr("width", cellSize - 2)
    .attr("height", cellSize - 2)
    .attr("fill", d => d3.interpolateRdYlGn(d.price / 100));

// 4. Real-time Update Simulation
