    data.forEach(d => {
        // Randomly fluctuate price
        d.price = Math.max(0, Math.min(100, d.price + (Math.random() - 0.5) * 10));
    });

    cells.transition().duration(500)
        .attr("fill", d => d3.interpolateRdYlGn(d.price / 100));
}, 1000);
