### 2. The Implementation

```html
<div id="heatmap"></div>

<script>
const width = 900, height = 600;
const svg = d3.select("#heatmap").append("svg")
    .attr("viewBox", [0, 0, width, height]);

// 1. Initial Data Structure
let data = {
    name: "Market",
    children: [
        { name: "AAPL", value: 150, change: 2.5 },
        { name: "GOOGL", value: 2800, change: -1.2 },
        { name: "TSLA", value: 700, change: 4.8 }
    ]
};

// 2. Color Scale (Red for negative, Green for positive)
const color = d3.scaleLinear()
    .domain([-5, 0, 5])
    .range(["#ff4d4d", "#333", "#2ecc71"]);

function render() {
    const root = d3.hierarchy(data).sum(d => d.value);
    d3.treemap().size([width, height]).padding(1)(root);

    const nodes = svg.selectAll("g").data(root.leaves(), d => d.data.name);

    const entering = nodes.enter().append("g")
        .attr("transform", d => `translate(${d.x0},${d.y0})`);

    entering.append("rect")
        .attr("class", "node")
        .attr("width", d => d.x1 - d.x0)
        .attr("height", d => d.y1 - d.y0)
        .attr("fill", d => color(d.data.change));

    entering.append("text")
        .attr("class", "label")
        .attr("x", 5).attr("y", 15)
        .text(d => `${d.data.name} (${d.data.change}%)`);

    // Update existing nodes
    nodes.select("rect").transition().attr("fill", d => color(d.data.change));
}

// 3. Zoom and Pan Behavior
const zoom = d3.zoom().scaleExtent([1, 8]).on("zoom", (event) => {
    svg.selectAll("g").attr("transform", event.transform);
});
svg.call(zoom);

// 4. Real-time update simulation
setInterval(() => {
    data.children.forEach(d => d.change += (Math.random() - 0.5) * 2);
    render();
}, 2000);

render();
</script>
```

### Key Technical Considerations

#### 1. Performance (Canvas vs. SVG)
*   **SVG (Used above):** Best for up to ~500 stocks. It allows easy CSS styling and event listeners (hover effects, tooltips).
*   **Canvas:** If you are tracking thousands of tickers, switch the `d3.select("svg")` to a `<canvas>` element. You would then use `context.fillRect()` inside your render loop instead of appending DOM elements.

#### 2. Real-time Data Handling
*   **WebSockets:** In a production app, replace the `setInterval` with a WebSocket connection (e.g., Finnhub or Alpaca API).
*   **Diffing:** The code above re-renders the whole tree. For high-frequency updates, use D3's `.join()` pattern (as shown) to update only the specific `fill` attributes of the rectangles rather than re-calculating the layout every time.

#### 3. UX/Interaction
*   **Zoom/Pan:** The `d3.zoom` behavior is applied to the container. As you zoom, the `transform` attribute is applied to the parent group, creating a smooth "infinite canvas" feel.
*   **Color Logic:** The `d3.scaleLinear` domain `[-5, 0, 5]` ensures that a 0% change is neutral (dark gray), while deviations move towards bright red or green.

#### 4. Next Steps for Production
1.  **Tooltips:** Add a `d3-tip` library to show full company names and volume on hover.
2.  **Debouncing:** If your data feed is faster than 100ms, debounce the `render()` function to prevent UI blocking.
3.  **Responsive Design:** Use `ResizeObserver` to update the `width` and `height` variables when the browser window changes size.

