### 1. Prerequisites
You will need to install these dependencies:
```bash
npm install @dnd-kit/core @dnd-kit/sortable @dnd-kit/utilities
```

### 2. The Core Component (`Board.js`)
This code implements a simple Kanban board where you can drag tasks between columns.

```jsx
import React, { useState } from 'react';
import { DndContext, closestCenter } from '@dnd-kit/core';
import { arrayMove, SortableContext, verticalListSortingStrategy, useSortable } from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';

const Task = ({ id, content }) => {
  const { attributes, listeners, setNodeRef, transform, transition } = useSortable({ id });
  const style = { transform: CSS.Transform.toString(transform), transition };

  return (
    <div ref={setNodeRef} style={style} {...attributes} {...listeners} className="p-4 mb-2 bg-white rounded shadow cursor-grab">
      {content}
    </div>
  );
};

export default function KanbanBoard() {
  const [tasks, setTasks] = useState([
    { id: '1', content: 'Design System' },
    { id: '2', content: 'Setup Backend' },
    { id: '3', content: 'Write Documentation' },
  ]);

  const handleDragEnd = (event) => {
    const { active, over } = event;
    if (active.id !== over.id) {
      setTasks((items) => {
        const oldIndex = items.findIndex((t) => t.id === active.id);
        const newIndex = items.findIndex((t) => t.id === over.id);
        return arrayMove(items, oldIndex, newIndex);
      });
    }
  };

  return (
    <div className="p-10 bg-gray-100 min-h-screen">
      <h1 className="text-2xl font-bold mb-6">Project Board</h1>
      <DndContext collisionDetection={closestCenter} onDragEnd={handleDragEnd}>
        <SortableContext items={tasks} strategy={verticalListSortingStrategy}>
          {tasks.map((task) => <Task key={task.id} id={task.id} content={task.content} />)}
        </SortableContext>
      </DndContext>
    </div>
  );
}
```

