### 2. The Backend (Node.js + Socket.io)
This server broadcasts task movements to all connected clients.

```javascript
// server.js
const io = require("socket.io")(3001, { cors: { origin: "*" } });

let tasks = [
  { id: '1', content: 'Task 1', status: 'todo' },
  { id: '2', content: 'Task 2', status: 'done' }
];

io.on('connection', (socket) => {
  socket.emit('init', tasks);

  socket.on('task-moved', (updatedTasks) => {
    tasks = updatedTasks;
    socket.broadcast.emit('update', tasks);
  });
});
```

