### 3. The Frontend (React)
This component handles the drag-and-drop logic and real-time syncing.

```jsx
import React, { useState, useEffect } from 'react';
import { DndContext, closestCenter } from '@dnd-kit/core';
import { arrayMove, SortableContext, verticalListSortingStrategy } from '@dnd-kit/sortable';
import io from 'socket.io-client';

const socket = io('http://localhost:3001');

export default function KanbanBoard() {
  const [tasks, setTasks] = useState([]);

  useEffect(() => {
    socket.on('init', (data) => setTasks(data));
    socket.on('update', (data) => setTasks(data));
  }, []);

  const handleDragEnd = (event) => {
    const { active, over } = event;
    if (active.id !== over.id) {
      const oldIndex = tasks.findIndex(t => t.id === active.id);
      const newIndex = tasks.findIndex(t => t.id === over.id);
      const newTasks = arrayMove(tasks, oldIndex, newIndex);

      setTasks(newTasks);
      socket.emit('task-moved', newTasks);
    }
  };

  return (
    <DndContext collisionDetection={closestCenter} onDragEnd={handleDragEnd}>
      <div className="board">
        {['todo', 'done'].map(status => (
          <div key={status} className="column">
            <h2>{status.toUpperCase()}</h2>
            <SortableContext items={tasks.filter(t => t.status === status)} strategy={verticalListSortingStrategy}>
              {tasks.filter(t => t.status === status).map(task => (
                <div key={task.id} className="task-card">{task.content}</div>
              ))}
            </SortableContext>
          </div>
        ))}
      </div>
    </DndContext>
  );
}
```

