#### The Kanban Board Component (`src/App.js`)
This code handles the board state and syncs it with Firestore in real-time.

```javascript
import React, { useState, useEffect } from 'react';
import { db } from './firebase';
import { collection, onSnapshot, doc, updateDoc } from 'firebase/firestore';
import { DndContext, closestCenter } from '@dnd-kit/core';
import { SortableContext, verticalListSortingStrategy } from '@dnd-kit/sortable';

function App() {
  const [tasks, setTasks] = useState([]);

  // Real-time sync with Firebase
  useEffect(() => {
    const unsub = onSnapshot(collection(db, "tasks"), (snapshot) => {
      setTasks(snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() })));
    });
    return unsub;
  }, []);

  const handleDragEnd = async (event) => {
    const { active, over } = event;
    if (active.id !== over.id) {
      // Update logic: In a real app, update the 'status' field in Firestore
      const taskRef = doc(db, "tasks", active.id);
      await updateDoc(taskRef, { status: over.id });
    }
  };

  return (
    <DndContext collisionDetection={closestCenter} onDragEnd={handleDragEnd}>
      <div style={{ display: 'flex', gap: '20px', padding: '20px' }}>
        {['Todo', 'Doing', 'Done'].map(status => (
          <div key={status} style={{ width: '300px', background: '#eee' }}>
            <h3>{status}</h3>
            {tasks.filter(t => t.status === status).map(task => (
              <div key={task.id} style={{ padding: '10px', margin: '5px', background: 'white' }}>
                {task.title}
              </div>
            ))}
          </div>
        ))}
      </div>
    </DndContext>
  );
}

export default App;
```

### 4. Key Components Explained

1.  **`onSnapshot` (Real-time Collaboration):** This is the "magic" function from Firebase. Whenever any user updates a task in the database, every other connected user's screen will update instantly without a page refresh.
2.  **`dnd-kit`:** This is the modern standard for drag-and-drop in React. It is accessible, lightweight, and handles complex pointer events better than older libraries like `react-beautiful-dnd`.
3.  **Firestore Structure:**
    *   Collection: `tasks`
    *   Document fields: `{ title: "Fix bug", status: "Todo", order: 1 }`

