### 4. The JavaScript (app.js)
This script uses Firebase Firestore to sync data across all connected browsers.

```javascript
import { initializeApp } from "https://www.gstatic.com/firebasejs/9.0.0/firebase-app.js";
import { getFirestore, collection, addDoc, onSnapshot, doc, updateDoc } from "https://www.gstatic.com/firebasejs/9.0.0/firebase-firestore.js";

const firebaseConfig = { /* Your Firebase Config Object */ };
const app = initializeApp(firebaseConfig);
const db = getFirestore(app);

// 1. Real-time Listener: Updates board whenever DB changes
onSnapshot(collection(db, "tasks"), (snapshot) => {
  document.getElementById('tasks-todo').innerHTML = '';
  document.getElementById('tasks-inprogress').innerHTML = '';

  snapshot.forEach((doc) => {
    const task = doc.data();
    const el = `<div class="task" draggable="true" ondragstart="drag(event)" id="${doc.id}">${task.text}</div>`;
    document.getElementById(`tasks-${task.status}`).innerHTML += el;
  });
});

// 2. Drag and Drop Logic
function allowDrop(ev) { ev.preventDefault(); }

function drag(ev) { ev.dataTransfer.setData("text", ev.target.id); }

async function drop(ev) {
  ev.preventDefault();
  const taskId = ev.dataTransfer.getData("text");
  const newStatus = ev.target.closest('.column').id.replace('tasks-', '');

  // Update Firebase in real-time
  await updateDoc(doc(db, "tasks", taskId), { status: newStatus });
}

// 3. Add Task
async function addTask() {
  const text = document.getElementById('taskInput').value;
  await addDoc(collection(db, "tasks"), { text, status: 'todo' });
}
```

