*Note: You need to set up a free project at [Firebase Console](https://console.firebase.google.com/) and paste your config.*

```javascript
import { initializeApp } from "https://www.gstatic.com/firebasejs/9.0.0/firebase-app.js";
import { getDatabase, ref, set, onValue, push } from "https://www.gstatic.com/firebasejs/9.0.0/firebase-database.js";

const firebaseConfig = { /* YOUR FIREBASE CONFIG HERE */ };
const app = initializeApp(firebaseConfig);
const db = getDatabase(app);

// Drag and Drop Handlers
window.allowDrop = (ev) => ev.preventDefault();

window.drop = (ev) => {
    ev.preventDefault();
    const taskId = ev.dataTransfer.getData("text");
    const newStatus = ev.currentTarget.id; // 'todo' or 'done'
    set(ref(db, 'tasks/' + taskId + '/status'), newStatus);
};

// Add Task
window.addTask = () => {
    const text = document.getElementById('taskInput').value;
    push(ref(db, 'tasks'), { text, status: 'todo' });
};

// Real-time Sync
onValue(ref(db, 'tasks'), (snapshot) => {
    const data = snapshot.val() || {};
    document.getElementById('todo-list').innerHTML = '';
    document.getElementById('done-list').innerHTML = '';

    Object.keys(data).forEach(id => {
        const task = data[id];
        const el = document.createElement('div');
        el.className = "bg-white p-2 mb-2 cursor-move";
        el.draggable = true;
        el.innerText = task.text;
        el.id = id;
        el.ondragstart = (e) => e.dataTransfer.setData("text", id);

        document.getElementById(task.status + '-list').appendChild(el);
    });
});
```

