```jsx
import React, { useState, useEffect } from 'react';
import { DragDropContext, Droppable, Draggable } from '@hello-pangea/dnd';
import { db } from './firebase';
import { doc, getDoc, updateDoc, onSnapshot } from 'firebase/firestore';

function App() {
  const [data, setData] = useState({ columns: { 'todo': [], 'done': [] } });

  // 1. Real-time sync with Firestore
  useEffect(() => {
    const unsub = onSnapshot(doc(db, "boards", "main"), (doc) => {
      setData(doc.data());
    });
    return () => unsub();
  }, []);

  // 2. Handle Drag End
  const onDragEnd = async (result) => {
    const { source, destination } = result;
    if (!destination) return;

    const newData = { ...data };
    const [movedItem] = newData.columns[source.droppableId].splice(source.index, 1);
    newData.columns[destination.droppableId].splice(destination.index, 0, movedItem);

    setData(newData);
    await updateDoc(doc(db, "boards", "main"), newData);
  };

  return (
    <DragDropContext onDragEnd={onDragEnd}>
      <div className="flex gap-4 p-8">
        {Object.entries(data.columns).map(([columnId, tasks]) => (
          <Droppable droppableId={columnId} key={columnId}>
            {(provided) => (
              <div {...provided.droppableProps} ref={provided.innerRef} className="bg-gray-100 p-4 w-64 rounded">
                <h2 className="font-bold mb-4 uppercase">{columnId}</h2>
                {tasks.map((task, index) => (
                  <Draggable key={task.id} draggableId={task.id} index={index}>
                    {(provided) => (
                      <div ref={provided.innerRef} {...provided.draggableProps} {...provided.dragHandleProps} className="bg-white p-2 mb-2 shadow rounded">
                        {task.content}
                      </div>
                    )}
                  </Draggable>
                ))}
                {provided.placeholder}
              </div>
            )}
          </Droppable>
        ))}
      </div>
    </DragDropContext>
  );
}
```

