import React, { useState, useEffect } from 'react';
import { DndContext, closestCenter } from '@dnd-kit/core';
import { arrayMove, SortableContext, verticalListSortingStrategy, useSortable } from '@dnd-kit/sortable';
import { collection, onSnapshot, doc, updateDoc } from 'firebase/firestore';
import { db } from './firebase';

// Simple Task Component
const Task = ({ id, content }) => {
  const { attributes, listeners, setNodeRef, transform, transition } = useSortable({ id });
  const style = { transform: transform ? `translate3d(${transform.x}px, ${transform.y}px, 0)` : undefined, transition };

  return (
    <div ref={setNodeRef} style={style} {...attributes} {...listeners} className="task">
      {content}
    </div>
  );
};

export default function App() {
  const [tasks, setTasks] = useState([]);

  // Real-time sync with Firestore
  useEffect(() => {
    const unsub = onSnapshot(collection(db, "tasks"), (snapshot) => {
      setTasks(snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() })));
    });
    return unsub;
  }, []);

  const handleDragEnd = async (event) => {
    const { active, over } = event;
    if (active.id !== over.id) {
      const oldIndex = tasks.findIndex(t => t.id === active.id);
      const newIndex = tasks.findIndex(t => t.id === over.id);
      const newTasks = arrayMove(tasks, oldIndex, newIndex);
      setTasks(newTasks);

      // Update Firestore
      await updateDoc(doc(db, "tasks", active.id), { order: newIndex });
    }
  };

  return (
    <DndContext collisionDetection={closestCenter} onDragEnd={handleDragEnd}>
      <div className="board">
        <SortableContext items={tasks} strategy={verticalListSortingStrategy}>
          {tasks.map(task => <Task key={task.id} id={task.id} content={task.content} />)}
        </SortableContext>
      </div>
    </DndContext>
  );
}
```

