### 1. The Core Pattern: The Disruptor (SPSC Queue)
Instead of using `std::mutex`, which causes context switching and kernel-level locks, we use a single-producer, single-consumer (SPSC) ring buffer with atomic memory barriers.

```cpp
#include <atomic>
#include <vector>

template<typename T, size_t Size>
class RingBuffer {
    T buffer[Size];
    alignas(64) std::atomic<size_t> head{0};
    alignas(64) std::atomic<size_t> tail{0};

public:
    bool push(const T& item) {
        size_t t = tail.load(std::memory_order_relaxed);
        size_t next_t = (t + 1) % Size;
        if (next_t == head.load(std::memory_order_acquire)) return false; // Full
        buffer[t] = item;
        tail.store(next_t, std::memory_order_release);
        return true;
    }

    bool pop(T& item) {
        size_t h = head.load(std::memory_order_relaxed);
        if (h == tail.load(std::memory_order_acquire)) return false; // Empty
        item = buffer[h];
        head.store((h + 1) % Size, std::memory_order_release);
        return true;
    }
};
```

