### 1. The Core Architecture: The Lock-Free Ring Buffer
Instead of using mutexes (which cause context switching and kernel overhead), we use a single-producer, single-consumer (SPSC) lock-free queue.

```cpp
#include <atomic>
#include <vector>
#include <optional>

// A simple SPSC Ring Buffer for inter-thread communication
template<typename T, size_t Capacity>
class RingBuffer {
    std::vector<T> buffer{Capacity};
    std::atomic<size_t> head{0};
    std::atomic<size_t> tail{0};

public:
    bool push(const T& item) {
        size_t t = tail.load(std::memory_order_relaxed);
        size_t next_t = (t + 1) % Capacity;
        if (next_t == head.load(std::memory_order_acquire)) return false; // Full
        buffer[t] = item;
        tail.store(next_t, std::memory_order_release);
        return true;
    }

    std::optional<T> pop() {
        size_t h = head.load(std::memory_order_relaxed);
        if (h == tail.load(std::memory_order_acquire)) return std::nullopt; // Empty
        T item = buffer[h];
        head.store((h + 1) % Capacity, std::memory_order_release);
        return item;
    }
};
```

