### 2. Core Implementation: The SPSC Queue
The backbone of a scalable trading system is the messaging bus. A lock-free queue allows the Gateway (receiving market data) to talk to the Strategy Engine without blocking.

```cpp
#include <atomic>
#include <vector>

template<typename T, size_t Capacity>
class SPSCQueue {
    T buffer[Capacity];
    std::atomic<size_t> head{0};
    std::atomic<size_t> tail{0};

public:
    bool push(const T& item) {
        size_t t = tail.load(std::memory_order_relaxed);
        size_t next_t = (t + 1) % Capacity;
        if (next_t == head.load(std::memory_order_acquire)) return false; // Full
        buffer[t] = item;
        tail.store(next_t, std::memory_order_release);
        return true;
    }

    bool pop(T& item) {
        size_t h = head.load(std::memory_order_relaxed);
        if (h == tail.load(std::memory_order_acquire)) return false; // Empty
        item = buffer[h];
        head.store((h + 1) % Capacity, std::memory_order_release);
        return true;
    }
};
```

