    Order order;
    while (true) {
        if (input.pop(order)) {
            // Logic: Match order against book
            // For now, just pass through
            output.push(order);
        }
    }
}

int main() {
    RingBuffer<Order, 1024> inbound_queue;
    RingBuffer<Order, 1024> outbound_queue;

    std::thread engine(matching_engine, std::ref(inbound_queue), std::ref(outbound_queue));

    // Pin thread to a specific CPU core for latency consistency
    // (OS specific: pthread_setaffinity_np)

    engine.join();
    return 0;
}
