```cpp
#include <atomic>
#include <vector>
#include <chrono>
#include <iostream>

struct Message {
    uint64_t id;
    uint64_t timestamp_ns;
    char payload[64];
};

class RingBuffer {
    static constexpr size_t SIZE = 1024 * 1024; // Must be power of 2
    Message buffer[SIZE];
    alignas(64) std::atomic<size_t> head{0};
    alignas(64) std::atomic<size_t> tail{0};

public:
    bool try_push(const Message& msg) {
        size_t t = tail.load(std::memory_order_relaxed);
        if (t - head.load(std::memory_order_acquire) >= SIZE) return false;
        buffer[t & (SIZE - 1)] = msg;
        tail.store(t + 1, std::memory_order_release);
        return true;
    }

    bool try_pop(Message& msg) {
        size_t h = head.load(std::memory_order_relaxed);
        if (h == tail.load(std::memory_order_acquire)) return false;
        msg = buffer[h & (SIZE - 1)];
        head.store(h + 1, std::memory_order_release);
        return true;
    }
};

// Latency Monitor
void consumer(RingBuffer& rb) {
    Message msg;
    while (true) {
        if (rb.try_pop(msg)) {
            auto now = std::chrono::high_resolution_clock::now().time_since_epoch().count();
            auto latency = now - msg.timestamp_ns;
            // Log/Bucket latency for histogram analysis
        }
    }
}
```

