// Lock-free Ring Buffer for single-producer, single-consumer
class RingBuffer {
    static constexpr size_t SIZE = 1024 * 1024; // Power of 2
    Message buffer[SIZE];
    alignas(64) std::atomic<size_t> head{0};
    alignas(64) std::atomic<size_t> tail{0};

