### 2. Implementation: The Lock-Free Ring Buffer

This core component acts as the message bus.

```cpp
#include <atomic>
#include <vector>
#include <iostream>
#include <immintrin.h> // For _mm_pause()

template<typename T, size_t Capacity>
class RingBuffer {
    alignas(64) T buffer[Capacity];
    alignas(64) std::atomic<size_t> head{0};
    alignas(64) std::atomic<size_t> tail{0};

public:
    bool try_push(const T& item) {
        size_t t = tail.load(std::memory_order_relaxed);
        size_t next_t = (t + 1) % Capacity;
        if (next_t == head.load(std::memory_order_acquire)) return false;

        buffer[t] = item;
        tail.store(next_t, std::memory_order_release);
        return true;
    }

    bool try_pop(T& item) {
        size_t h = head.load(std::memory_order_relaxed);
        if (h == tail.load(std::memory_order_acquire)) return false;

        item = buffer[h];
        head.store((h + 1) % Capacity, std::memory_order_release);
        return true;
    }
};
```

