This orchestrator pins threads to cores and runs the main loop.

```cpp
#include <thread>
#include <pthread.h>

void pin_thread(int core_id) {
    cpu_set_t cpuset;
    CPU_ZERO(&cpuset);
    CPU_SET(core_id, &cpuset);
    pthread_setaffinity_np(pthread_self(), sizeof(cpu_set_t), &cpuset);
}

void producer_loop(RingBuffer<Message, 65536>& rb) {
    pin_thread(1);
    uint64_t count = 0;
    while (true) {
        Message m{count++, get_nanos()};
        while (!rb.try_push(m)) { _mm_pause(); } // Busy-wait
    }
}

void consumer_loop(RingBuffer<Message, 65536>& rb) {
    pin_thread(2);
    Message m;
    while (true) {
        if (rb.try_pop(m)) {
            uint64_t latency = get_nanos() - m.timestamp_ns;
            // Log latency metrics periodically...
        } else {
            _mm_pause(); // Efficient busy-wait
        }
    }
}
```

