	latency := time.Now().UnixNano() - msg.Timestamp

	atomic.AddUint64(&r.metrics.processedCount, 1)
	atomic.AddInt64(&r.metrics.totalLatency, latency)
}

func (r *Router) Enqueue(msg Message) {
	r.msgQueue <- msg
}
