### 1. The Core Architecture (The Ring Buffer)
For high-frequency messaging, you cannot use `std::queue` or `std::vector` with mutexes. We use a **Disruptor (Ring Buffer)** to pass pointers to messages between threads without locks.

```cpp
#include <atomic>
#include <vector>
#include <chrono>

struct Message {
    uint64_t id;
    uint64_t timestamp_ns;
    char payload[128];
};

// Simple lock-free Ring Buffer for high-speed IPC
template<size_t Size>
class RingBuffer {
    Message buffer[Size];
    std::atomic<size_t> head{0};
    std::atomic<size_t> tail{0};

public:
    bool try_push(const Message& msg) {
        size_t t = tail.load(std::memory_order_relaxed);
        if (t - head.load(std::memory_order_acquire) >= Size) return false;
        buffer[t % Size] = msg;
        tail.store(t + 1, std::memory_order_release);
        return true;
    }

    bool try_pop(Message& msg) {
        size_t h = head.load(std::memory_order_relaxed);
        if (h == tail.load(std::memory_order_acquire)) return false;
        msg = buffer[h % Size];
        head.store(h + 1, std::memory_order_release);
        return true;
    }
};
```

