### Minimal Implementation (Go)

```go
package main

import (
	"fmt"
	"sync/atomic"
	"time"
)

const (
	RingSize = 1024 * 64 // Must be power of 2
	Mask     = RingSize - 1
)

type Message struct {
	Timestamp int64
	Payload   int
}

func main() {
	ring := make([]Message, RingSize)
	var head uint64 // Producer index
	var tail uint64 // Consumer index
	var latencySum int64
	var processedCount uint64

	// Consumer: Processes messages and tracks latency
	go func() {
		for {
			currentTail := atomic.LoadUint64(&tail)
			if currentTail < atomic.LoadUint64(&head) {
				msg := &ring[currentTail&Mask]

				// Calculate Latency
				latency := time.Now().UnixNano() - msg.Timestamp
				atomic.AddInt64(&latencySum, latency)
				atomic.AddUint64(&processedCount, 1)

				atomic.StoreUint64(&tail, currentTail+1)
			}
		}
	}()

	// Producer: Injects messages
	for i := 0; i < 1_000_000; i++ {
		for {
			h := atomic.LoadUint64(&head)
			if h-atomic.LoadUint64(&tail) < RingSize {
				ring[h&Mask] = Message{Timestamp: time.Now().UnixNano(), Payload: i}
				atomic.StoreUint64(&head, h+1)
				break
			}
		}
	}

	time.Sleep(time.Second)
	fmt.Printf("Processed: %d, Avg Latency: %dns\n", 
		processedCount, latencySum/int64(processedCount))
}
```

