    static class Message { long timestamp; long data; }

    private static final int BUFFER_SIZE = 1024 * 64; // Must be power of 2
    private static final Message[] ringBuffer = new Message[BUFFER_SIZE];
    private static final AtomicLong cursor = new AtomicLong(0);

    static {
