        consumer.start();

        // Producer Thread (Simulating millions of MPS)
        while (true) {
            long next = cursor.get() + 1;
            Message msg = ringBuffer[(int) (next & (BUFFER_SIZE - 1))];
            msg.timestamp = System.nanoTime();
            msg.data = next;
            cursor.set(next); // Publish
        }
    }
}
