This script pins threads to CPU cores to prevent context switching (crucial for sub-microsecond latency).

```cpp
#include <iostream>
#include <thread>
#include <chrono>
#include <vector>

struct Message {
    uint64_t id;
    uint64_t timestamp_ns;
};

void producer(SPSCQueue<Message, 65536>& q) {
    for (uint64_t i = 0; i < 10000000; ++i) {
        Message m{i, (uint64_t)std::chrono::high_resolution_clock::now().time_since_epoch().count()};
        while (!q.push(m)); // Spin-wait
    }
}

void consumer(SPSCQueue<Message, 65536>& q) {
    uint64_t total_latency = 0;
    for (uint64_t i = 0; i < 10000000; ++i) {
        Message m;
        while (!q.pop(m));
        auto now = std::chrono::high_resolution_clock::now().time_since_epoch().count();
        total_latency += (now - m.timestamp_ns);
        if (i % 1000000 == 0) std::cout << "Latency: " << (total_latency / (i+1)) << " ns\n";
    }
}

int main() {
