### 1. The Core: Lock-Free Ring Buffer
We use a power-of-two sized buffer to allow bitwise masking (`&`) instead of the expensive modulo (`%`) operator.

```cpp
#include <iostream>
#include <atomic>
#include <vector>
#include <chrono>

struct Message {
    uint64_t id;
    uint64_t timestamp;
    char payload[64];
};

template<size_t Capacity>
class RingBuffer {
    static_assert((Capacity & (Capacity - 1)) == 0, "Capacity must be power of 2");
    Message buffer[Capacity];
    alignas(64) std::atomic<size_t> head{0};
    alignas(64) std::atomic<size_t> tail{0};

public:
    bool push(const Message& msg) {
        size_t t = tail.load(std::memory_order_relaxed);
        if (t - head.load(std::memory_order_acquire) >= Capacity) return false;
        buffer[t & (Capacity - 1)] = msg;
        tail.store(t + 1, std::memory_order_release);
        return true;
    }

    bool pop(Message& msg) {
        size_t h = head.load(std::memory_order_relaxed);
        if (h == tail.load(std::memory_order_acquire)) return false;
        msg = buffer[h & (Capacity - 1)];
        head.store(h + 1, std::memory_order_release);
        return true;
    }
};
```

### 2. The Producer & Consumer (Latency Monitor)
We pin threads to CPU cores using `pthread_setaffinity_np` to prevent context switching, which is the primary killer of HFT latency.

```cpp
