RingBuffer<65536> rb;

void producer() {
    uint64_t count = 0;
    while (true) {
        Message m{count++, (uint64_t)std::chrono::high_resolution_clock::now().time_since_epoch().count()};
        while (!rb.push(m)); // Busy wait (Spinlock)
    }
}

void consumer() {
