```java
import java.util.concurrent.atomic.AtomicLong;

public class MinimalHFTSystem {
    // Ring buffer size (must be power of 2 for fast masking)
    private static final int SIZE = 1024 * 64;
    private static final long[] buffer = new long[SIZE];
    private static final long[] timestamps = new long[SIZE];

    // Sequence numbers (Volatile for memory visibility)
    private static volatile long head = 0;
    private static volatile long tail = 0;

    public static void main(String[] args) throws InterruptedException {
        // Consumer Thread
        Thread consumer = new Thread(() -> {
            long totalLatency = 0;
            long count = 0;
            while (true) {
                if (tail < head) {
                    long index = tail & (SIZE - 1);
                    long msg = buffer[(int) index];
                    long sentTime = timestamps[(int) index];

                    totalLatency += (System.nanoTime() - sentTime);
                    count++;

                    if (count % 1_000_000 == 0) {
                        System.out.printf("Avg Latency: %.2f ns%n", (double) totalLatency / count);
                    }
                    tail++;
                }
            }
        });

        consumer.setPriority(Thread.MAX_PRIORITY);
        consumer.start();

        // Producer Loop
        for (long i = 0; i < 10_000_000; i++) {
            // Busy wait if buffer full
            while (head - tail >= SIZE) { Thread.onSpinWait(); }

            int index = (int) (head & (SIZE - 1));
            timestamps[index] = System.nanoTime();
            buffer[index] = i;
            head++;
        }
    }
}
```

