This snippet demonstrates the core loop of a packet-level filter/forwarder.

```c
#include <rte_eal.h>
#include <rte_ethdev.h>
#include <rte_mbuf.h>

#define BURST_SIZE 32

static void lcore_main_loop(uint16_t port) {
    struct rte_mbuf *bufs[BURST_SIZE];

    while (1) {
        // 1. Poll the NIC for packets (Zero-copy)
        uint16_t nb_rx = rte_eth_rx_burst(port, 0, bufs, BURST_SIZE);

        for (int i = 0; i < nb_rx; i++) {
            struct rte_ether_hdr *eth_hdr = rte_pktmbuf_mtod(bufs[i], struct rte_ether_hdr *);

            // 2. Packet-level filtering (e.g., Drop all non-IPv4)
            if (ntohs(eth_hdr->ether_type) != RTE_ETHER_TYPE_IPV4) {
                rte_pktmbuf_free(bufs[i]);
                continue;
            }

            // 3. Forwarding (Swap MACs or send to another port)
            // In a real app, you would update headers here
            rte_eth_tx_burst(port ^ 1, 0, &bufs[i], 1);
        }
    }
}
```

