    // 3. Fast-path Loop (The "Hot Path")
    struct rte_mbuf *bufs[BURST_SIZE];
    while (1) {
        // Poll NIC for packets
        const uint16_t nb_rx = rte_eth_rx_burst(0, 0, bufs, BURST_SIZE);

        if (unlikely(nb_rx == 0)) continue;

        uint16_t nb_tx = 0;
        for (int i = 0; i < nb_rx; i++) {
            // --- PACKET FILTERING LOGIC ---
            // Example: Drop packets that aren't IPv4
            struct rte_ether_hdr *eth_hdr = rte_pktmbuf_mtod(bufs[i], struct rte_ether_hdr *);
            if (eth_hdr->ether_type != rte_cpu_to_be_16(RTE_ETHER_TYPE_IPV4)) {
                rte_pktmbuf_free(bufs[i]);
                continue; 
            }

            // --- FORWARDING LOGIC ---
            // Swap MAC addresses or forward to another port
            bufs[nb_tx++] = bufs[i];
        }

        // Send packets out
        if (nb_tx > 0) {
            rte_eth_tx_burst(0, 0, bufs, nb_tx);
        }
    }
    return 0;
}
