#include <rte_eal.h>
#include <rte_ethdev.h>
#include <rte_mbuf.h>

#define RX_RING_SIZE 1024
#define TX_RING_SIZE 1024
#define NUM_MBUFS 8191
#define MBUF_CACHE_SIZE 250
#define BURST_SIZE 32

static const struct rte_eth_conf port_conf_default = {
    .rxmode = { .max_rx_pkt_len = RTE_ETHER_MAX_LEN }
};

int main(int argc, char *argv[]) {
    // 1. Initialize EAL
    int ret = rte_eal_init(argc, argv);
    if (ret < 0) rte_exit(EXIT_FAILURE, "Error with EAL initialization\n");

    // 2. Create Memory Pool
    struct rte_mempool *mbuf_pool = rte_pktmbuf_pool_create("MBUF_POOL", NUM_MBUFS, 
        MBUF_CACHE_SIZE, 0, RTE_MBUF_DEFAULT_BUF_SIZE, rte_socket_id());

    // 3. Initialize Port (Assuming port 0)
    uint16_t port_id = 0;
    rte_eth_dev_configure(port_id, 1, 1, &port_conf_default);
    rte_eth_rx_queue_setup(port_id, 0, RX_RING_SIZE, rte_eth_dev_socket_id(port_id), NULL, mbuf_pool);
    rte_eth_tx_queue_setup(port_id, 0, TX_RING_SIZE, rte_eth_dev_socket_id(port_id), NULL);
    rte_eth_dev_start(port_id);

    // 4. Main Processing Loop
    struct rte_mbuf *bufs[BURST_SIZE];
    while (1) {
        const uint16_t nb_rx = rte_eth_rx_burst(port_id, 0, bufs, BURST_SIZE);

        for (int i = 0; i < nb_rx; i++) {
            struct rte_ether_hdr *eth_hdr = rte_pktmbuf_mtod(bufs[i], struct rte_ether_hdr *);

            // --- PACKET FILTERING LOGIC ---
            // Example: Drop all non-IPv4 packets
            if (ntohs(eth_hdr->ether_type) != RTE_ETHER_TYPE_IPV4) {
                rte_pktmbuf_free(bufs[i]);
                continue;
            }

            // --- FORWARDING LOGIC ---
            // In a real app, you'd modify MAC addresses here
            rte_eth_tx_burst(port_id, 0, &bufs[i], 1);
        }
    }
    return 0;
}
```

### Key Architectural Concepts for Ultra-Low Latency

1.  **Poll Mode Drivers (PMD):** Unlike standard Linux networking, which uses interrupts (causing context switches), this code uses a `while(1)` loop. This keeps the CPU core pinned to the NIC, checking for packets constantly, which eliminates the latency of waking up from sleep.
2.  **Zero-Copy:** The `rte_mbuf` structures point directly to memory mapped into the NIC's DMA space. The CPU never "copies" the packet data; it only updates pointers.
3.  **Hugepages:** By using 2MB or 1GB pages instead of 4KB pages, you significantly reduce TLB (Translation Lookaside Buffer) misses, which is critical for maintaining consistent latency (jitter).
4.  **CPU Isolation:** To truly achieve ultra-low latency, you must isolate the CPU core running this loop from the OS scheduler using the kernel boot parameter `isolcpus=1`.

