#include <rte_eal.h>
#include <rte_ethdev.h>
#include <rte_mbuf.h>

#define RX_RING_SIZE 1024
#define TX_RING_SIZE 1024
#define NUM_MBUFS 8191
#define MBUF_CACHE_SIZE 250
#define BURST_SIZE 32

static const struct rte_eth_conf port_conf_default = {
    .rxmode = { .max_rx_pkt_len = RTE_ETHER_MAX_LEN }
};

int main(int argc, char *argv[]) {
    // 1. Initialize EAL (Environment Abstraction Layer)
    int ret = rte_eal_init(argc, argv);
    if (ret < 0) rte_exit(EXIT_FAILURE, "Error with EAL init\n");

    // 2. Create Memory Pool for packets
    struct rte_mempool *mbuf_pool = rte_pktmbuf_pool_create("MBUF_POOL", NUM_MBUFS, 
                                     MBUF_CACHE_SIZE, 0, RTE_MBUF_DEFAULT_BUF_SIZE, rte_socket_id());

    // 3. Initialize Port (Simplified - assumes port 0)
    rte_eth_dev_configure(0, 1, 1, &port_conf_default);
    rte_eth_rx_queue_setup(0, 0, RX_RING_SIZE, rte_eth_dev_socket_id(0), NULL, mbuf_pool);
    rte_eth_tx_queue_setup(0, 0, TX_RING_SIZE, rte_eth_dev_socket_id(0), NULL);
    rte_eth_dev_start(0);

    // 4. Main Processing Loop
    struct rte_mbuf *bufs[BURST_SIZE];
    while (1) {
        // Poll packets
        const uint16_t nb_rx = rte_eth_rx_burst(0, 0, bufs, BURST_SIZE);

        uint16_t nb_tx = 0;
        for (int i = 0; i < nb_rx; i++) {
            struct rte_ether_hdr *eth_hdr = rte_pktmbuf_mtod(bufs[i], struct rte_ether_hdr *);

            // --- PACKET FILTERING LOGIC ---
            // Example: Drop all IPv6 traffic (EtherType 0x86DD)
            if (rte_be_to_cpu_16(eth_hdr->ether_type) == RTE_ETHER_TYPE_IPV6) {
                rte_pktmbuf_free(bufs[i]);
                continue;
            }

            // Forward valid packets
            bufs[nb_tx++] = bufs[i];
        }

        // Send packets
        if (nb_tx > 0) {
            rte_eth_tx_burst(0, 0, bufs, nb_tx);
        }
    }
    return 0;
}
```

