#include <rte_eal.h>
#include <rte_ethdev.h>
#include <rte_mbuf.h>

#define RX_RING_SIZE 1024
#define TX_RING_SIZE 1024
#define NUM_MBUFS 8191
#define MBUF_CACHE_SIZE 250

int main(int argc, char *argv[]) {
    // 1. Initialize EAL (Environment Abstraction Layer)
    int ret = rte_eal_init(argc, argv);
    struct rte_mempool *mbuf_pool = rte_pktmbuf_pool_create("MBUF_POOL", NUM_MBUFS, 
                                    MBUF_CACHE_SIZE, 0, RTE_MBUF_DEFAULT_BUF_SIZE, rte_socket_id());

    // 2. Configure Ethernet Port (Simplified)
    struct rte_eth_conf port_conf = {0};
    rte_eth_dev_configure(0, 1, 1, &port_conf);
    rte_eth_rx_queue_setup(0, 0, RX_RING_SIZE, rte_socket_id(), NULL, mbuf_pool);
    rte_eth_tx_queue_setup(0, 0, TX_RING_SIZE, rte_socket_id(), NULL);
    rte_eth_dev_start(0);

    // 3. Main Loop (The "Fast Path")
    struct rte_mbuf *bufs[32];
    while (1) {
        // Receive packets
        const uint16_t nb_rx = rte_eth_rx_burst(0, 0, bufs, 32);

        for (int i = 0; i < nb_rx; i++) {
            // Packet-level filtering (Example: Drop if not IPv4)
            struct rte_ether_hdr *eth_hdr = rte_pktmbuf_mtod(bufs[i], struct rte_ether_hdr *);
            if (eth_hdr->ether_type != rte_cpu_to_be_16(RTE_ETHER_TYPE_IPV4)) {
                rte_pktmbuf_free(bufs[i]);
                continue;
            }

            // Forwarding (Swap MACs or just send back out)
            rte_eth_tx_burst(0, 0, &bufs[i], 1);
        }
    }
    return 0;
}
```

