#include <string.h>
#include <sys/socket.h>
#include <linux/if_packet.h>
#include <net/ethernet.h>
#include <net/if.h>
#include <sys/ioctl.h>
#include <unistd.h>

#define BUFFER_SIZE 2048

int main() {
    int sock_in, sock_out;
    struct sockaddr_ll sll;
    unsigned char buffer[BUFFER_SIZE];

    // 1. Create Raw Socket (ETH_P_ALL captures all incoming traffic)
    sock_in = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    sock_out = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));

    // 2. Bind to specific interfaces (replace "eth0" and "eth1")
    // Use ioctl to get interface indices
    struct ifreq ifr;

    strncpy(ifr.ifr_name, "eth0", IFNAMSIZ);
    ioctl(sock_in, SIOCGIFINDEX, &ifr);
    sll.sll_family = AF_PACKET;
    sll.sll_ifindex = ifr.ifr_ifindex;
    bind(sock_in, (struct sockaddr *)&sll, sizeof(sll));

    strncpy(ifr.ifr_name, "eth1", IFNAMSIZ);
    ioctl(sock_out, SIOCGIFINDEX, &ifr);
    sll.sll_ifindex = ifr.ifr_ifindex;

    printf("Forwarding started...\n");

    while (1) {
        int len = recvfrom(sock_in, buffer, BUFFER_SIZE, 0, NULL, NULL);

        // 3. Packet-level filtering (Example: Drop if first byte is 0xAA)
        if (buffer[0] == 0xAA) continue;

        // 4. Ultra-low latency forwarding
        sendto(sock_out, buffer, len, 0, (struct sockaddr *)&sll, sizeof(sll));
    }

    return 0;
}
```

