package main

import (
	"compress/gzip"
	"io"
	"log"
	"os"
	"path/filepath"
	"runtime"
	"time"
)

const (
	MaxLogSize = 10 * 1024 * 1024 // 10MB
	LogDir     = "./logs"
	BufSize    = 64 * 1024        // 64KB buffer
)

func rotateLog(path string) error {
	// 1. Rename current log to .old
	oldPath := path + ".old"
	if err := os.Rename(path, oldPath); err != nil {
		return err
	}

	// 2. Open files for streaming
	src, err := os.Open(oldPath)
	if err != nil {
		return err
	}
	defer src.Close()

	dst, err := os.Create(path + "." + time.Now().Format("20060102") + ".gz")
	if err != nil {
		return err
	}
	defer dst.Close()

	// 3. Stream through Gzip writer (Memory efficient)
	gw := gzip.NewWriter(dst)
	defer gw.Close()

	buf := make([]byte, BufSize)
	_, err = io.CopyBuffer(gw, src, buf)

	// 4. Cleanup
	src.Close()
	os.Remove(oldPath)

	// Force GC to reclaim the buffer immediately
	runtime.GC() 
	return err
}

func monitor() {
	for {
		files, _ := filepath.Glob(filepath.Join(LogDir, "*.log"))
		for _, f := range files {
			info, _ := os.Stat(f)
			if info.Size() > MaxLogSize {
				if err := rotateLog(f); err != nil {
					log.Printf("Error rotating %s: %v", f, err)
				}
			}
		}
		time.Sleep(10 * time.Second)
	}
}

func main() {
