import (
	"fmt"
	"io"
	"os"
	"path/filepath"
	"time"
)

const (
	MaxLogSize = 10 * 1024 * 1024 // 10MB limit
	BufferSize = 32 * 1024        // 32KB fixed memory buffer
)

type Rotator struct {
	LogPath string
}

func (r *Rotator) Rotate() error {
	info, err := os.Stat(r.LogPath)
	if err != nil || info.Size() < MaxLogSize {
		return err
	}

	backupPath := fmt.Sprintf("%s.%d.bak", r.LogPath, time.Now().Unix())

	// 1. Rename current file to backup
	if err := os.Rename(r.LogPath, backupPath); err != nil {
		return err
	}

	// 2. Create new empty file
	newFile, err := os.OpenFile(r.LogPath, os.O_CREATE|os.O_WRONLY, 0644)
	if err != nil {
		return err
	}
	newFile.Close()

	return nil
}

// Memory-efficient processor for existing large logs
func CompressBackup(srcPath string) error {
	src, err := os.Open(srcPath)
	if err != nil {
		return err
	}
	defer src.Close()

	// Using a fixed buffer prevents loading the whole file into memory
	buf := make([]byte, BufferSize)

	// Example: just reading to simulate processing without holding in RAM
	for {
		_, err := src.Read(buf)
		if err == io.EOF {
			break
		}
		// Process chunks here...
	}
	return nil
}

func main() {
	rotator := &Rotator{LogPath: "/var/log/myapp.log"}

	for {
		if err := rotator.Rotate(); err != nil {
			fmt.Printf("Rotation error: %v\n", err)
		}
		time.Sleep(1 * time.Minute)
	}
}
```

### How this satisfies the constraints:

1.  **Heap Stability:** The `make([]byte, BufferSize)` allocation happens once. The Garbage Collector (GC) will not be triggered by file-processing load because the memory usage is flat.
2.  **OS-Level Offloading:** By using `os.Rename`, we avoid reading the file contents during the rotation event. The OS handles the file pointer shift, which is an $O(1)$ operation in terms of memory.
3.  **Backpressure:** If you add compression (e.g., `gzip.Writer`), you should wrap the `io.Writer` in a `bufio.Writer` to ensure you only ever hold `BufferSize` amount of data in flight.

