            let mem_usage = self.sys.used_memory() as f64 / self.sys.total_memory() as f64 * 100.0;

            info!("CPU: {:.2}% | RAM: {:.2}%", cpu_usage, mem_usage);

            // Logic for resource management (e.g., killing rogue processes)
            if cpu_usage > 95.0 {
                self.handle_high_load();
            }
        }
    }

    fn handle_high_load(&self) {
        error!("High load detected! Triggering mitigation...");
        // Implement logic: e.g., send signals to specific PIDs
    }
}

