    CPUStats prev = get_cpu_stats();

    while (true) {
        std::this_thread::sleep_for(std::chrono::seconds(1));

        CPUStats curr = get_cpu_stats();

        long total_diff = (curr.user + curr.nice + curr.system + curr.idle) - 
                          (prev.user + prev.nice + prev.system + prev.idle);
        long idle_diff = curr.idle - prev.idle;

        double cpu_usage = 100.0 * (total_diff - idle_diff) / total_diff;

        // Logic: If CPU usage > 90%, log to syslog or take action
        if (cpu_usage > 90.0) {
            // In a real system, use openlog() and syslog() here
        }

        prev = curr;
    }
    return 0;
}
```

