    double cpu_usage;
    long mem_free;
};

class MonitorDaemon {
    int epoll_fd;
    bool running = true;

    void collect_metrics() {
        // High-performance parsing: read /proc/stat
        std::ifstream stat_file("/proc/stat");
        std::string line;
        std::getline(stat_file, line); // First line contains total CPU
        std::cout << "[METRIC] CPU Line: " << line << std::endl;
        // Logic to calculate delta between ticks goes here
    }

public:
    MonitorDaemon() {
        epoll_fd = epoll_create1(0);
    }

    void run() {
        int timer_fd = timerfd_create(CLOCK_MONOTONIC, 0);
        itimerspec ts;
        ts.it_interval = {1, 0}; // 1 second interval
        ts.it_value = {1, 0};
        timerfd_settime(timer_fd, 0, &ts, nullptr);

        epoll_event event;
        event.events = EPOLLIN;
        event.data.fd = timer_fd;
        epoll_ctl(epoll_fd, EPOLL_CTL_ADD, timer_fd, &event);

        while (running) {
            epoll_event events[1];
            int n = epoll_wait(epoll_fd, events, 1, -1);
            if (n > 0) {
                uint64_t exp;
                read(timer_fd, &exp, sizeof(uint64_t));
                collect_metrics();
            }
        }
    }
};

int main() {
    // Daemonize
    if (daemon(0, 0) == -1) return 1;

    MonitorDaemon daemon;
    daemon.run();
    return 0;
}
```

### Key Performance Strategies

#### 1. Zero-Allocation Parsing
Avoid `std::string` and `std::stringstream` inside the hot loop. Use fixed-size character buffers and `std::string_view` to parse `/proc` files. This prevents heap fragmentation and keeps the cache warm.

#### 2. Efficient I/O with `epoll`
Instead of `sleep()`, which puts the thread in an uninterruptible state, use `timerfd` combined with `epoll`. This allows the daemon to remain responsive to other events (like Unix signals or IPC requests) while waiting for the next monitoring cycle.

#### 3. Avoiding Context Switches
If you need to monitor thousands of processes, do not spawn a thread per process. Use a single-threaded event loop (as shown above) to keep the CPU cache locality high and avoid the overhead of context switching between threads.

#### 4. Memory Mapping
If you need to log large amounts of data, use `mmap()` to map log files into memory. This allows the OS kernel to handle writing the data to disk asynchronously without blocking your main execution loop.

