#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <unistd.h>
#include <sys/epoll.h>
#include <sys/timerfd.h>
#include <signal.h>

class ResourceMonitor {
public:
    ResourceMonitor() : stop(false) {}

    void run() {
        int timer_fd = setup_timer(1); // 1-second interval
        int epoll_fd = epoll_create1(0);

        struct epoll_event ev, events[1];
        ev.events = EPOLLIN;
        ev.data.fd = timer_fd;
        epoll_ctl(epoll_fd, EPOLL_CTL_ADD, timer_fd, &ev);

        while (!stop) {
            int nfds = epoll_wait(epoll_fd, events, 1, -1);
            if (nfds > 0) {
                uint64_t expirations;
                read(timer_fd, &expirations, sizeof(uint64_t));
                collect_metrics();
            }
        }
    }

private:
    bool stop;

    int setup_timer(int seconds) {
        int fd = timerfd_create(CLOCK_MONOTONIC, 0);
        struct itimerspec ts;
        ts.it_interval.tv_sec = seconds;
        ts.it_interval.tv_nsec = 0;
        ts.it_value.tv_sec = seconds;
        ts.it_value.tv_nsec = 0;
        timerfd_settime(fd, 0, &ts, NULL);
        return fd;
    }

    void collect_metrics() {
        // High-performance: read /proc/stat directly
        std::ifstream file("/proc/stat");
        std::string line;
        std::getline(file, line);
        // In a real system, parse the CPU jiffies here
        std::cout << "[Monitor] Sampled CPU metrics: " << line << std::endl;
    }
};

int main() {
    // Daemonize: Fork and detach
    if (daemon(0, 0) < 0) return 1;

    ResourceMonitor monitor;
    monitor.run();
    return 0;
}
```

