#define MAX_EVENTS 5

void daemonize() {
    pid_t pid = fork();
    if (pid < 0) exit(EXIT_FAILURE);
    if (pid > 0) exit(EXIT_SUCCESS);
    if (setsid() < 0) exit(EXIT_FAILURE);

    // Redirect standard streams to /dev/null
    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    open("/dev/null", O_RDONLY);
    open("/dev/null", O_RDWR);
    open("/dev/null", O_RDWR);
}

void monitor_resources() {
    // In a real system, you would read /proc/stat or /proc/meminfo
    // Here we simulate the logic loop
    syslog(LOG_INFO, "Resource monitor cycle triggered.");
}

int main() {
    daemonize();
    openlog("sys-monitor-d", LOG_PID, LOG_DAEMON);
    syslog(LOG_INFO, "Daemon started.");

    int epoll_fd = epoll_create1(0);
    struct epoll_event event, events[MAX_EVENTS];

    // Main loop
    while (1) {
        // High-performance wait (1-second interval)
        int nfds = epoll_wait(epoll_fd, events, MAX_EVENTS, 1000);

        monitor_resources();
    }

    closelog();
    return 0;
}
```

