        self.sys.refresh_cpu();
        self.sys.refresh_memory();

        let cpu_usage = self.sys.global_cpu_info().cpu_usage();
        let mem_usage = (self.sys.used_memory() as f32 / self.sys.total_memory() as f32) * 100.0;

        info!("System Stats: CPU {:.2}%, RAM {:.2}%", cpu_usage, mem_usage);

        if cpu_usage > CPU_THRESHOLD {
            warn!("High CPU usage detected: {:.2}%", cpu_usage);
        }

        if mem_usage > MEM_THRESHOLD {
            warn!("High Memory usage detected: {:.2}%", mem_usage);
        }
    }
}

