```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <syslog.h>
#include <fcntl.h>

static volatile int keep_running = 1;

void signal_handler(int sig) {
    keep_running = 0;
}

void daemonize() {
    pid_t pid = fork();

    if (pid < 0) exit(EXIT_FAILURE);
    if (pid > 0) exit(EXIT_SUCCESS); // Parent exits
    if (setsid() < 0) exit(EXIT_FAILURE); // Become session leader

    signal(SIGCHLD, SIG_IGN);
    signal(SIGHUP, SIG_IGN);

    pid = fork(); // Second fork to ensure we aren't a session leader
    if (pid < 0) exit(EXIT_FAILURE);
    if (pid > 0) exit(EXIT_SUCCESS);

    umask(0);
    chdir("/");

    // Redirect standard files to /dev/null
    for (int x = sysconf(_SC_OPEN_MAX); x >= 0; x--) {
        close(x);
    }
    openlog("sys_monitor", LOG_PID, LOG_DAEMON);
}

int main() {
    daemonize();
    syslog(LOG_NOTICE, "System Monitor Daemon started.");

    struct sigaction action;
    action.sa_handler = signal_handler;
    sigaction(SIGTERM, &action, NULL);

    while (keep_running) {
        // PERFORMANCE NOTE: Use epoll() here if monitoring 
        // sockets or multiple file descriptors.

        // Example: Monitor CPU/Memory by reading /proc
        syslog(LOG_INFO, "Monitoring system resources...");

        sleep(5); // Adjust frequency based on performance requirements
    }

    syslog(LOG_NOTICE, "System Monitor Daemon terminated.");
    closelog();
    return EXIT_SUCCESS;
}
```

### Key Performance Considerations

1.  **Avoid Polling where possible:** Instead of reading `/proc` files in a loop (which incurs syscall overhead), use **`inotify`** to watch for changes in `/proc` or `/sys` files, or use **`netlink`** sockets to get kernel events (like process starts/exits) directly from the kernel.
2.  **Memory Management:** Pre-allocate buffers for your monitoring data. Never use dynamic memory allocation (`malloc`) inside the main loop to avoid heap fragmentation and latency spikes.
3.  **Syscalls:** Syscalls are expensive. If you need to monitor high-frequency metrics, aggregate them in memory and perform a single batch write to your log or database.
4.  **CPU Affinity:** If the daemon performs heavy processing, use `pthread_setaffinity_np` to pin the daemon to a specific CPU core, preventing context switching overhead.

