#include <stdlib.h>
#include <unistd.h>
#include <sys/epoll.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <syslog.h>

#define MAX_EVENTS 5

void daemonize() {
    if (fork() > 0) exit(0); // Parent exits
    setsid();                // Create new session
    umask(0);                // Set file mode
    chdir("/");              // Change to root
    close(STDIN_FILENO);     // Close standard streams
    close(STDOUT_FILENO);
    close(STDERR_FILENO);
}

