#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <syslog.h>

void daemonize() {
    pid_t pid = fork();
    if (pid < 0) exit(EXIT_FAILURE);
    if (pid > 0) exit(EXIT_SUCCESS);
    if (setsid() < 0) exit(EXIT_FAILURE);

    // Redirect standard streams to /dev/null
    freopen("/dev/null", "r", stdin);
    freopen("/dev/null", "w", stdout);
    freopen("/dev/null", "w", stderr);
}

int main() {
    daemonize();
    openlog("res_monitor", LOG_PID, LOG_DAEMON);

    while (1) {
        // High-performance monitoring: read /proc/stat directly
        FILE* fp = fopen("/proc/stat", "r");
        if (fp) {
            char buffer[256];
            fgets(buffer, sizeof(buffer), fp);
            syslog(LOG_INFO, "CPU Stats: %s", buffer);
            fclose(fp);
        }

        sleep(5); // Adjust interval for performance requirements
    }

    closelog();
    return 0;
}
```

