struct tpacket_req3 req = {
    .tp_block_size = 1024 * 1024, // 1MB blocks
    .tp_frame_size = 2048,        // Fits standard MTU
    .tp_block_nr   = 64,          // 64MB buffer
    .tp_frame_nr   = (1024 * 1024 * 64) / 2048,
};

int setup_socket(const char* interface) {
