#include <netinet/ip.h>
#include <netinet/tcp.h>
#include <iostream>
#include <unordered_map>

// A simple 5-tuple key for flow tracking
struct FlowKey {
    uint32_t src_ip, dst_ip;
    uint16_t src_port, dst_port;
    uint8_t protocol;

    bool operator==(const FlowKey& other) const {
        return src_ip == other.src_ip && dst_ip == other.dst_ip &&
               src_port == other.src_port && dst_port == other.dst_port &&
               protocol == other.protocol;
    }
};

// Custom hasher for FlowKey
struct FlowHasher {
    size_t operator()(const FlowKey& k) const {
        return ((size_t)k.src_ip ^ (size_t)k.dst_ip) << 1; 
    }
};

std::unordered_map<FlowKey, uint64_t, FlowHasher> flow_stats;

void packet_handler(u_char* user, const struct pcap_pkthdr* pkthdr, const u_char* packet) {
    // Offset for Ethernet header (14 bytes)
    struct ip* ip_hdr = (struct ip*)(packet + 14);

    if (ip_hdr->ip_p == IPPROTO_TCP) {
        struct tcphdr* tcp_hdr = (struct tcphdr*)(packet + 14 + (ip_hdr->ip_hl << 2));

        FlowKey key = {ip_hdr->ip_src.s_addr, ip_hdr->ip_dst.s_addr, 
                       tcp_hdr->source, tcp_hdr->dest, IPPROTO_TCP};

        flow_stats[key] += pkthdr->len;
    }
}

