    // "eth0" should be replaced with your interface
    pcap_t* handle = pcap_open_live("eth0", 65535, 1, 1000, errbuf);

    // Set immediate mode for low latency
    pcap_set_immediate_mode(handle, 1);

    // Increase buffer size to 128MB to prevent drops during spikes
    pcap_set_buffer_size(handle, 128 * 1024 * 1024);

    pcap_loop(handle, 0, packet_handler, NULL);
    return 0;
}
