    // 1. Setup Memory Mapped Ring Buffer
    struct tpacket_req req = {
        .tp_block_size = FRAME_SIZE * 128,
        .tp_frame_size = FRAME_SIZE,
        .tp_block_nr = 32,
        .tp_frame_nr = FRAME_COUNT
    };
    setsockopt(sock, SOL_PACKET, PACKET_RX_RING, &req, sizeof(req));

    void *ring = mmap(NULL, req.tp_block_size * req.tp_block_nr, 
                      PROT_READ | PROT_WRITE, MAP_SHARED, sock, 0);

    struct tpacket_hdr *header = (struct tpacket_hdr *)ring;

    printf("Monitoring traffic...\n");

    // 2. Zero-Copy Processing Loop
    while (1) {
        if (header->tp_status & TP_STATUS_USER) {
            // Access packet data directly in the shared buffer
            unsigned char *data = (unsigned char *)header + header->tp_mac;

            // Minimal logic: Print Ethernet Type (Performance critical: keep this light)
            printf("Packet captured, length: %u\n", header->tp_len);

            // Return control of the frame to the kernel
            header->tp_status = TP_STATUS_KERNEL;
            header = (void *)header + FRAME_SIZE;
            if ((void *)header >= (void *)ring + (req.tp_block_size * req.tp_block_nr))
                header = ring;
        }
    }
    return 0;
}
