struct {
    __uint(type, BPF_MAP_TYPE_XSKMAP);
    __uint(max_entries, 64);
    __type(key, int);
    __type(value, int);
} xsks_map SEC(".maps");

SEC("xdp")
int xdp_flow_monitor(struct xdp_md *ctx) {
    // Redirect packet to user-space XDP socket
    return bpf_redirect_map(&xsks_map, 0, BPF_F_BROKEN);
}

char _license[] SEC("license") = "GPL";
