#include <Wire.h>
#include <Adafruit_BME280.h>

// Configuration
#define SENSOR_READ_INTERVAL 2000 // Read every 2 seconds
#define ALPHA 0.2                 // Smoothing factor for EMA filter

// Global Variables
Adafruit_BME280 bme;
unsigned long lastReadTime = 0;
float filteredTemp = 0.0;

// Simple Exponential Moving Average (EMA) filter to reduce noise
float applyFilter(float newValue, float oldValue) {
    return (ALPHA * newValue) + ((1.0 - ALPHA) * oldValue);
}

void setup() {
    Serial.begin(115200);

    if (!bme.begin(0x76)) {
        Serial.println("Could not find a valid BME280 sensor!");
        while (1);
    }

    Serial.println("Sensor initialized. Starting loop...");
}

void loop() {
    unsigned long currentMillis = millis();

    // Non-blocking timing check
    if (currentMillis - lastReadTime >= SENSOR_READ_INTERVAL) {
        lastReadTime = currentMillis;

        // 1. Read Raw Data
        float rawTemp = bme.readTemperature();

        // 2. Process Data (Filtering)
        filteredTemp = applyFilter(rawTemp, filteredTemp);

        // 3. Output Data
        Serial.print("Raw: "); Serial.print(rawTemp);
        Serial.print(" | Filtered: "); Serial.println(filteredTemp);

        // 4. Logic/Threshold Check
        if (filteredTemp > 30.0) {
            // Trigger an alert or fan
            Serial.println("ALERT: High Temperature!");
        }
    }

    // You can perform other tasks here without blocking the sensor read
}
```

