const int RELAY_PIN = 9;        // Pin connected to a heater/fan
const int THRESHOLD = 300;      // Threshold for triggering action
const int NUM_READINGS = 10;    // Number of readings for averaging

// Variables
int readings[NUM_READINGS];     // Array to store readings
int readIndex = 0;              // Current index in array
long total = 0;                 // Running total
int average = 0;                // Final smoothed value

void setup() {
  pinMode(SENSOR_PIN, INPUT);
  pinMode(RELAY_PIN, OUTPUT);

  // Initialize serial for debugging
  Serial.begin(9600);

  // Initialize readings array to 0
  for (int i = 0; i < NUM_READINGS; i++) {
    readings[i] = 0;
  }
}

void loop() {
  // 1. Process: Update Moving Average
  total = total - readings[readIndex];       // Subtract last reading
  readings[readIndex] = analogRead(SENSOR_PIN); // Read new sensor value
  total = total + readings[readIndex];       // Add new reading
  readIndex++;                               // Advance to next position

  if (readIndex >= NUM_READINGS) {
    readIndex = 0;                           // Wrap around
  }

  average = total / NUM_READINGS;            // Calculate average

  // 2. Logic: Act based on processed data
  if (average > THRESHOLD) {
    digitalWrite(RELAY_PIN, HIGH);           // Turn on output
  } else {
    digitalWrite(RELAY_PIN, LOW);            // Turn off output
  }

  // 3. Output: Debugging info
  Serial.print("Raw: ");
  Serial.print(readings[readIndex-1]);
  Serial.print(" | Smoothed: ");
  Serial.println(average);

  delay(50); // Small delay for stability
}
```

