const unsigned long readInterval = 100; // Read every 100ms

void setup() {
    pinMode(LED_PIN, OUTPUT);
    Serial.begin(9600);

    // Initialize smoothing array
    for (int i = 0; i < NUM_READINGS; i++) {
        readings[i] = 0;
    }
}

// Function to convert ADC value to Celsius
float getTemperature() {
    int raw = analogRead(SENSOR_PIN);
    // Example formula: (Raw / 1023) * 5V * 100 (assuming 10mV/deg)
    return (raw * 5.0 / 1023.0) * 100.0;
}

void loop() {
    unsigned long currentMillis = millis();

    // Non-blocking timer: Run sensor logic every 100ms
    if (currentMillis - lastReadTime >= readInterval) {
        lastReadTime = currentMillis;

        // 1. Subtract the last reading from total
        total = total - readings[readIndex];

        // 2. Read new sensor data
        readings[readIndex] = getTemperature();

        // 3. Add to total and increment index
        total = total + readings[readIndex];
        readIndex++;

        // 4. Wrap index around
        if (readIndex >= NUM_READINGS) {
            readIndex = 0;
        }

        // 5. Calculate average
        average = total / NUM_READINGS;

        // 6. Process logic
        if (average > TEMP_THRESHOLD) {
            digitalWrite(LED_PIN, HIGH); // Alarm ON
        } else {
            digitalWrite(LED_PIN, LOW);  // Alarm OFF
        }

        Serial.print("Temp: ");
        Serial.println(average);
    }
}
```

