#include <stdint.h>

// Configuration
#define SENSOR_PIN A0
#define THRESHOLD 75.0
#define SAMPLES 10

// Function Prototypes
float read_sensor(int pin);
float apply_moving_average(float new_value);

void setup() {
    Serial.begin(9600);
    pinMode(SENSOR_PIN, INPUT);
}

void loop() {
    // 1. Read raw data
    float raw_value = read_sensor(SENSOR_PIN);

    // 2. Process data (Filter noise)
    float filtered_value = apply_moving_average(raw_value);

    // 3. Logic/Decision making
    if (filtered_value > THRESHOLD) {
        Serial.print("ALERT: High Temp! ");
    }

    Serial.println(filtered_value);

    delay(100); // Sampling rate control
}

// Read and convert to meaningful units (e.g., Celsius)
float read_sensor(int pin) {
    int adc_value = analogRead(pin);
    // Example conversion: ADC 0-1023 to 0-100 degrees
    return (adc_value * (100.0 / 1023.0));
}

// Simple Moving Average Filter to stabilize jittery sensor data
float apply_moving_average(float new_value) {
    static float buffer[SAMPLES] = {0};
    static int index = 0;
    static float sum = 0;

    sum -= buffer[index];
    buffer[index] = new_value;
    sum += buffer[index];

    index = (index + 1) % SAMPLES;

    return sum / SAMPLES;
}
