#define SAMPLE_SIZE 10        // Number of samples for the moving average
#define READ_INTERVAL 100     // Read sensor every 100ms

// --- Global Variables ---
float sensorBuffer[SAMPLE_SIZE];
int bufferIndex = 0;
unsigned long lastReadTime = 0;

// --- Function Prototypes ---
float processSensorData(int rawValue);

void setup() {
    Serial.begin(9600);
    pinMode(SENSOR_PIN, INPUT);

    // Initialize buffer with zeros
    for(int i = 0; i < SAMPLE_SIZE; i++) sensorBuffer[i] = 0;
}

void loop() {
    unsigned long currentTime = millis();

    // Non-blocking timer
    if (currentTime - lastReadTime >= READ_INTERVAL) {
        lastReadTime = currentTime;

        // 1. Read Raw Data
        int rawValue = analogRead(SENSOR_PIN);

        // 2. Process Data
        float filteredValue = processSensorData(rawValue);

        // 3. Output/Action
        Serial.print("Raw: ");
        Serial.print(rawValue);
        Serial.print(" | Filtered: ");
        Serial.println(filteredValue);
    }
}

/**
 * Implements a simple Moving Average Filter
 * Reduces noise from the analog signal
 */
float processSensorData(int rawValue) {
    sensorBuffer[bufferIndex] = rawValue;
    bufferIndex = (bufferIndex + 1) % SAMPLE_SIZE;

    float sum = 0;
    for(int i = 0; i < SAMPLE_SIZE; i++) {
        sum += sensorBuffer[i];
    }

    return sum / SAMPLE_SIZE;
}
```

