### The Code

```cpp
// Define the pin connected to your sensor
const int sensorPin = A0; 

// Variables for processing
float smoothedValue = 0;
const float alpha = 0.1; // Smoothing factor (0 < alpha < 1)

void setup() {
  // Initialize serial communication for debugging
  Serial.begin(9600);
}

void loop() {
  // 1. READ: Get raw data from the sensor (0 to 1023)
  int rawValue = analogRead(sensorPin);

  // 2. PROCESS: Simple Exponential Moving Average (Low-pass filter)
  // Formula: New = (alpha * Current) + ((1 - alpha) * Previous)
  smoothedValue = (alpha * rawValue) + ((1.0 - alpha) * smoothedValue);

  // 3. OUTPUT: Send data to the serial monitor
  Serial.print("Raw: ");
  Serial.print(rawValue);
  Serial.print(" | Processed: ");
  Serial.println(smoothedValue);

  // Small delay to prevent flooding the serial port
  delay(50);
}
```

