const float alpha = 0.1; // Smoothing factor (0 < alpha < 1)

void setup() {
  // Initialize Serial for debugging
  Serial.begin(9600);
}

void loop() {
  // 1. READ: Get raw data from the ADC (0-1023)
  int rawValue = analogRead(sensorPin);

  // 2. PROCESS: Simple Exponential Moving Average (EMA) filter
  // Formula: New = (Alpha * Raw) + ((1 - Alpha) * Old)
