  // 3. OUTPUT: Send processed data to the computer
  Serial.print("Raw: ");
  Serial.print(rawValue);
  Serial.print(" | Filtered: ");
  Serial.println(filteredValue);

  // Small delay to stabilize the loop
  delay(50);
}
```

