        return 0.98f * (fused_angle + gyro * dt) + 0.02f * accel;
    }

    // PID Controller
    float computePID(float setpoint, float measured) {
        float error = setpoint - measured;
        integral += error * dt;
        float derivative = (error - last_error) / dt;
        last_error = error;
        return (Kp * error) + (Ki * integral) + (Kd * derivative);
    }

public:
    void run() {
        Sensor gyro, accel;
        Motor motor;

        while (true) {
            auto start = std::chrono::steady_clock::now();

            // 1. Data Acquisition
            float g = gyro.getRawData();
            float a = accel.getRawData();

            // 2. Sensor Fusion
            fused_angle = updateFusion(g, a);

            // 3. Control Logic
            float output = computePID(0.0f, fused_angle);

            // 4. Actuation
            motor.setPower(output);

            // 5. Real-time Timing (Maintain fixed frequency)
            auto end = std::chrono::steady_clock::now();
            std::this_thread::sleep_until(start + std::chrono::milliseconds(10));
        }
