            SensorData raw_data = read_hardware_sensors();

            // 2. Sensor Fusion
            double state = fuse_sensors(raw_data);

            // 3. Compute Control Output
            double command = compute_pid(10.0, state, 1.0/frequency_hz);

            // 4. Actuate
            write_to_motors({command});

            // 5. Real-time synchronization
            next_wake += std::chrono::duration_cast<std::chrono::steady_clock::duration>(period);
            std::this_thread::sleep_until(next_wake);
        }
    }

