// Simple PID Controller Class
class PID {
public:
    double kp, ki, kd, prev_error = 0, integral = 0;
    double update(double setpoint, double measured, double dt) {
        double error = setpoint - measured;
        integral += error * dt;
        double derivative = (error - prev_error) / dt;
        prev_error = error;
        return (kp * error) + (ki * integral) + (kd * derivative);
    }
};

// Sensor Fusion: Complementary Filter
// Combines Gyroscope (fast, drifts) and Accelerometer (slow, noisy)
double fuseSensors(double gyro_rate, double accel_angle, double dt) {
    static double angle = 0;
    const double alpha = 0.98; // Weighting factor
    angle = alpha * (angle + gyro_rate * dt) + (1.0 - alpha) * accel_angle;
    return angle;
}

std::atomic<bool> running(true);

void controlLoop() {
    PID motorPID{1.5, 0.1, 0.05};
    double dt = 0.01; // 100Hz loop

    while (running) {
        auto start = std::chrono::high_resolution_clock::now();

        // 1. READ SENSORS (Simulated)
        double gyro = readGyro(); 
        double accel = readAccel();
        double current_pos = readEncoder();

        // 2. SENSOR FUSION
        double fused_angle = fuseSensors(gyro, accel, dt);

        // 3. CONTROL LOGIC
        double target = 90.0; // Target angle
        double output = motorPID.update(target, fused_angle, dt);

        // 4. ACTUATE MOTORS
        writeMotor(output);

        // 5. TIMING CONTROL (Maintain 100Hz)
        auto end = std::chrono::high_resolution_clock::now();
        std::this_thread::sleep_for(std::chrono::milliseconds(10) - (end - start));
    }
}

int main() {
    std::thread controlThread(controlLoop);
    // ... handle system interrupts ...
