```c
#include <stdio.h>
#include <math.h>

#define WINDOW_SIZE 20
#define THRESHOLD 3.0 // Sensitivity: Z-score threshold

typedef struct {
    float buffer[WINDOW_SIZE];
    int index;
    float sum;
    float sq_sum;
} SensorStats;

// Initialize stats
void init_stats(SensorStats *s) {
    s->index = 0;
    s->sum = 0;
    s->sq_sum = 0;
    for(int i=0; i<WINDOW_SIZE; i++) s->buffer[i] = 0;
}

// Process new sample and return 1 if anomaly detected
int process_sample(SensorStats *s, float new_val) {
    // Remove old value from sum/sq_sum
    float old_val = s->buffer[s->index];
    s->sum -= old_val;
    s->sq_sum -= (old_val * old_val);

    // Add new value
    s->buffer[s->index] = new_val;
    s->sum += new_val;
    s->sq_sum += (new_val * new_val);

    // Calculate moving average and variance
    float mean = s->sum / WINDOW_SIZE;
    float variance = (s->sq_sum / WINDOW_SIZE) - (mean * mean);
    float std_dev = sqrtf(variance > 0 ? variance : 0);

    // Update index
    s->index = (s->index + 1) % WINDOW_SIZE;

    // Detect anomaly (Z-Score > Threshold)
    if (std_dev > 0.001f) {
        float z_score = fabsf(new_val - mean) / std_dev;
        return (z_score > THRESHOLD);
    }
    return 0;
}

int main() {
    SensorStats accel_x;
    init_stats(&accel_x);

    // Simulated stream
    float data[] = {1.0, 1.1, 1.0, 0.9, 1.0, 5.0}; // 5.0 is the anomaly

    for(int i=0; i<6; i++) {
        if(process_sample(&accel_x, data[i])) {
            printf("Anomaly detected at sample %d: %f\n", i, data[i]);
        }
    }
    return 0;
}
```

