#define THRESHOLD 3.0f // Standard deviations to trigger anomaly

typedef struct {
    float buffer[WINDOW_SIZE];
    int head;
    float sum;
    float sum_sq;
} RollingStats;

// Add new sample and update running sum/sum_sq
void update_stats(RollingStats *rs, float new_val) {
    float old_val = rs->buffer[rs->head];

    // Update rolling sums
    rs->sum = rs->sum - old_val + new_val;
    rs->sum_sq = rs->sum_sq - (old_val * old_val) + (new_val * new_val);

    // Store new value
    rs->buffer[rs->head] = new_val;
    rs->head = (rs->head + 1) % WINDOW_SIZE;
}

