    float mean = rs->sum / WINDOW_SIZE;
    float variance = (rs->sum_sq / WINDOW_SIZE) - (mean * mean);
    float std_dev = sqrtf(variance > 0 ? variance : 0);

    // Avoid division by zero
    if (std_dev < 0.01f) return 0; 

    float z_score = fabsf(val - mean) / std_dev;
    return (z_score > THRESHOLD);
}

