### 1. The Core Logic (C/C++)

This implementation calculates the mean and standard deviation in a single pass. If a new data point deviates from the mean by more than $N$ standard deviations, it is flagged as an anomaly.

```cpp
#include <stdio.h>
#include <math.h>

typedef struct {
    float mean;
    float m2;       // Sum of squares of differences from the mean
    int count;
    float threshold; // Number of standard deviations (e.g., 3.0)
} AnomalyDetector;

void init_detector(AnomalyDetector* d, float threshold) {
    d->mean = 0.0f;
    d->m2 = 0.0f;
    d->count = 0;
    d->threshold = threshold;
}

bool process_sample(AnomalyDetector* d, float x) {
    d->count++;
    float delta = x - d->mean;
    d->mean += delta / d->count;
    float delta2 = x - d->mean;
    d->m2 += delta * delta2;

    if (d->count < 10) return false; // Warm-up period

    float variance = d->m2 / (d->count - 1);
    float std_dev = sqrt(variance);

    // Anomaly detection: |x - mean| > threshold * std_dev
    return (fabs(x - d->mean) > (d->threshold * std_dev));
}
```

