    float buffer[WINDOW_SIZE];
    int index;
    int count;
    float sum;
    float sum_sq;
} SensorStats;

// Initialize the pipeline
void init_stats(SensorStats *s) {
    s->index = 0;
    s->count = 0;
    s->sum = 0;
    s->sum_sq = 0;
}

