bool process_sample(SensorStats *s, float new_val) {
    bool is_anomaly = false;

    if (s->count >= WINDOW_SIZE) {
        // Calculate current stats
        float mean = s->sum / WINDOW_SIZE;
        float variance = (s->sum_sq / WINDOW_SIZE) - (mean * mean);
        float std_dev = sqrtf(variance > 0 ? variance : 0);

        // Z-score check
        if (std_dev > 0.1f) { // Avoid divide by zero/noise
            float z_score = fabsf(new_val - mean) / std_dev;
            if (z_score > THRESHOLD) is_anomaly = true;
        }

        // Subtract oldest value from running totals
        float old_val = s->buffer[s->index];
        s->sum -= old_val;
        s->sum_sq -= (old_val * old_val);
