    // Add new value
    s->buffer[s->index] = new_val;
    s->sum += new_val;
    s->sum_sq += (new_val * new_val);

    // Increment circular buffer index
    s->index = (s->index + 1) % WINDOW_SIZE;

    return is_anomaly;
}

