```cpp
#include <stdio.h>
#include <math.h>

typedef struct {
    float mean;
    float m2;      // Used for Welford's algorithm
    int count;
    float threshold; // Number of std devs to trigger anomaly
} AnomalyDetector;

// Initialize the detector
void init_detector(AnomalyDetector *d, float threshold) {
    d->mean = 0.0f;
    d->m2 = 0.0f;
    d->count = 0;
    d->threshold = threshold;
}

// Process a new sample and return 1 if anomaly, 0 otherwise
int process_sample(AnomalyDetector *d, float sample) {
    d->count++;
    float delta = sample - d->mean;
    d->mean += delta / d->count;
    float delta2 = sample - d->mean;
    d->m2 += delta * delta2;

    if (d->count < 10) return 0; // Warm-up period

    float variance = d->m2 / (d->count - 1);
    float std_dev = sqrtf(variance);

    // Anomaly if outside threshold
    if (fabsf(sample - d->mean) > (d->threshold * std_dev)) {
        return 1; 
    }
    return 0;
}

int main() {
    AnomalyDetector accel = {0};
    init_detector(&accel, 3.0f); // 3-sigma threshold

    float stream[] = {1.0, 1.1, 0.9, 1.0, 1.05, 5.0, 0.9}; // 5.0 is the anomaly

    for (int i = 0; i < 7; i++) {
        if (process_sample(&accel, stream[i])) {
            printf("Anomaly detected at sample %d: %f\n", i, stream[i]);
        }
    }
    return 0;
}
```

