    uint8_t  index;
    uint32_t sum;
    bool     actuator_state;
} SensorController;

// Initialize state
void init_controller(SensorController* sc) {
    sc->index = 0;
    sc->sum = 0;
    sc->actuator_state = false;
}

// Moving Average Filter (O(1) complexity)
