    sc->sum -= sc->buffer[sc->index];      // Remove oldest
    sc->buffer[sc->index] = new_value;     // Add newest
    sc->sum += new_value;

    sc->index = (sc->index + 1) % SENSOR_BUFFER_SIZE; // Circular buffer

    return (uint16_t)(sc->sum / SENSOR_BUFFER_SIZE);
}

// Actuator logic
void update_actuator(SensorController* sc, uint16_t filtered_value) {
    if (filtered_value > THRESHOLD_HIGH && !sc->actuator_state) {
        // Turn ON actuator (e.g., GPIO_SET)
        sc->actuator_state = true;
    } else if (filtered_value < THRESHOLD_LOW && sc->actuator_state) {
        // Turn OFF actuator (e.g., GPIO_CLEAR)
        sc->actuator_state = false;
    }
}

// Main Loop
void loop() {
    static SensorController my_sensor;

    uint16_t raw_data = read_adc(); // Hardware abstraction call
    uint16_t clean_data = filter_sensor(&my_sensor, raw_data);

    update_actuator(&my_sensor, clean_data);

    // Sleep to save power (e.g., 100ms)
    delay_ms(100);
}
```

