#include <iostream>
#include <vector>

// Configuration for resource constraints
const float THRESHOLD = 70.0f;
const float ALPHA = 0.2f; // Smoothing factor for Exponential Moving Average

class EdgeController {
private:
    float filteredValue = 0.0f;
    bool isInitialized = false;

    // Efficient EMA Filter (O(1) memory complexity)
    float applyFilter(float rawValue) {
        if (!isInitialized) {
            filteredValue = rawValue;
            isInitialized = true;
        } else {
            // Formula: EMA = (Alpha * Current) + ((1 - Alpha) * Previous)
            filteredValue = (ALPHA * rawValue) + ((1.0f - ALPHA) * filteredValue);
        }
        return filteredValue;
    }

    void triggerActuator(float value) {
        if (value > THRESHOLD) {
            std::cout << "[ACTUATOR] High load detected: " << value << ". Activating cooling." << std::endl;
        } else {
            std::cout << "[ACTUATOR] Status normal: " << value << ". Idle." << std::endl;
        }
    }

public:
    void process(float rawSensorData) {
        float cleanData = applyFilter(rawSensorData);
        triggerActuator(cleanData);
    }
};

int main() {
    EdgeController edgeNode;

    // Simulated sensor stream
    std::vector<float> sensorStream = {65.0, 68.0, 72.0, 75.0, 71.0, 60.0};

    for (float val : sensorStream) {
        edgeNode.process(val);
    }

    return 0;
}
```

