        // 1. Data Acquisition
        int16_t rawData = tempSensor.read();

        // 2. Processing (Simple Moving Average or Thresholding)
        // Here we use a simple hysteresis threshold to prevent rapid switching
        if (rawData > TEMP_THRESHOLD && !fanState) {
            if (currentMillis - lastChangeTime > DEBOUNCE_MS) {
                fan.set(true);
                fanState = true;
                lastChangeTime = currentMillis;
            }
        } else if (rawData <= (TEMP_THRESHOLD - 50) && fanState) {
            fan.set(false);
            fanState = false;
            lastChangeTime = currentMillis;
        }
    }
};

