To build a real-time 3D scene viewer, **Three.js** is the industry standard for the web. It handles the WebGL boilerplate, allowing you to focus on shaders and lighting.

Below is a complete, single-file example. It includes a **dynamic light source** (that follows your mouse) and a **custom shader material** that creates a "pulsing" effect.

### The Code (`index.html`)

```html
<!DOCTYPE html>
<html>
<head>
    <style>body { margin: 0; overflow: hidden; } canvas { display: block; }</style>
</head>
<body>
    <script type="module">
        import * as THREE from 'https://unpkg.com/three@0.158.0/build/three.module.js';

        // 1. Scene Setup
        const scene = new THREE.Scene();
        const camera = new THREE.PerspectiveCamera(75, window.innerWidth/window.innerHeight, 0.1, 1000);
        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        document.body.appendChild(renderer.domElement);

        // 2. Custom Shader Material
        const uniforms = { time: { value: 0 } };
        const material = new THREE.ShaderMaterial({
            uniforms: uniforms,
            vertexShader: `
                varying vec2 vUv;
                uniform float time;
                void main() {
                    vUv = uv;
                    vec3 pos = position;
                    pos.z += sin(pos.x * 5.0 + time) * 0.2; // Wavy effect
                    gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
                }
            `,
            fragmentShader: `
                varying vec2 vUv;
                void main() {
                    gl_FragColor = vec4(vUv, 1.0, 1.0);
                }
            `
        });

        // 3. Objects
        const geometry = new THREE.TorusKnotGeometry(1, 0.3, 100, 16);
        const mesh = new THREE.Mesh(geometry, material);
        scene.add(mesh);

        // 4. Dynamic Lighting
        const light = new THREE.PointLight(0xffffff, 100);
        scene.add(light);
        scene.add(new THREE.AmbientLight(0x404040));

        camera.position.z = 5;

        // 5. Interaction & Animation
        window.addEventListener('mousemove', (e) => {
            light.position.x = (e.clientX / window.innerWidth) * 10 - 5;
            light.position.y = -(e.clientY / window.innerHeight) * 10 + 5;
        });

        function animate(t) {
            requestAnimationFrame(animate);
            uniforms.time.value = t * 0.005;
            mesh.rotation.x += 0.01;
            mesh.rotation.y += 0.01;
            renderer.render(scene, camera);
        }
        animate();
    </script>
</body>
</html>
```

