</body>
</html>
```

### 2. The Implementation (`main.js`)

```javascript
import * as THREE from 'https://unpkg.com/three@0.158.0/build/three.module.js';

// 1. Scene Setup
const scene = new THREE.Scene();
const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(window.innerWidth, window.innerHeight);
document.body.appendChild(renderer.domElement);

// 2. Custom Shader Material (Pulsing Effect)
const shaderMaterial = new THREE.ShaderMaterial({
    uniforms: { uTime: { value: 0 } },
    vertexShader: `
        varying vec2 vUv;
        void main() {
            vUv = uv;
            gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
        }
    `,
    fragmentShader: `
        uniform float uTime;
        varying vec2 vUv;
        void main() {
            gl_FragColor = vec4(0.5 + 0.5 * sin(uTime), vUv.x, vUv.y, 1.0);
        }
    `
});

// 3. Objects & Lighting
const geometry = new THREE.TorusKnotGeometry(1, 0.3, 100, 16);
const mesh = new THREE.Mesh(geometry, shaderMaterial);
scene.add(mesh);

const light = new THREE.PointLight(0xffffff, 50, 100);
scene.add(light);
scene.add(new THREE.AmbientLight(0x404040)); // Soft white light

camera.position.z = 5;

// 4. Interaction & Animation
window.addEventListener('mousemove', (e) => {
    light.position.x = (e.clientX / window.innerWidth) * 10 - 5;
    light.position.y = -(e.clientY / window.innerHeight) * 10 + 5;
});

function animate(time) {
    requestAnimationFrame(animate);

    // Update shader time
    shaderMaterial.uniforms.uTime.value = time * 0.002;

    // Rotate mesh
    mesh.rotation.x += 0.01;
    mesh.rotation.y += 0.01;

    renderer.render(scene, camera);
}

animate();
```

### Key Components Explained:

*   **`WebGLRenderer`**: The engine that bridges your JavaScript code with the GPU.
*   **`ShaderMaterial`**: This is where the magic happens.
    *   **Vertex Shader**: Handles the position of vertices (geometry).
    *   **Fragment Shader**: Determines the color of every pixel. By passing `uTime` as a uniform, we create dynamic, frame-by-frame color changes.
*   **`PointLight`**: This acts as a physical light source in the scene. We map the mouse X/Y coordinates to the light's position to make the lighting feel interactive.
*   **`requestAnimationFrame`**: The standard browser loop for high-performance 60FPS rendering.

