        import * as THREE from 'https://unpkg.com/three@0.158.0/build/three.module.js';

        // 1. Scene Setup
        const scene = new THREE.Scene();
        const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        document.body.appendChild(renderer.domElement);

        // 2. Custom Shader Material
        const vertexShader = `
            varying vec2 vUv;
            uniform float uTime;
            void main() {
                vUv = uv;
                vec3 pos = position;
                pos.z += sin(pos.x * 5.0 + uTime) * 0.2; // Wavy animation
                gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
            }
        `;

        const fragmentShader = `
            varying vec2 vUv;
            uniform float uTime;
            void main() {
                gl_FragColor = vec4(0.5 + 0.5 * sin(uTime), vUv.x, vUv.y, 1.0);
            }
        `;

        const material = new THREE.ShaderMaterial({
            uniforms: { uTime: { value: 0 } },
            vertexShader,
            fragmentShader,
            wireframe: true
        });

        // 3. Objects & Lighting
        const geometry = new THREE.SphereGeometry(1, 32, 32);
        const sphere = new THREE.Mesh(geometry, material);
        scene.add(sphere);

        const light = new THREE.PointLight(0xffffff, 100);
        light.position.set(5, 5, 5);
        scene.add(light);
        scene.add(new THREE.AmbientLight(0x404040));

        camera.position.z = 3;

        // 4. Animation Loop
        function animate(time) {
            requestAnimationFrame(animate);
            material.uniforms.uTime.value = time * 0.002;
            sphere.rotation.y += 0.01;
            renderer.render(scene, camera);
        }
        animate(0);
    </script>
</body>
</html>
```

### Key Components Explained:

1.  **The Scene Graph:** We create a `Scene`, `Camera`, and `Renderer`. The renderer converts the 3D math into pixels on your `<canvas>`.
2.  **Custom GLSL Shaders:**
    *   **Vertex Shader:** Manipulates the geometry's vertices on the GPU. We use `sin(uTime)` to make the mesh "breathe" or ripple in real-time.
    *   **Fragment Shader:** Determines the color of each pixel. Here, we map the color output to the passing time and the UV coordinates of the mesh.
3.  **Uniforms:** These are variables passed from JavaScript to the GPU (like `uTime`). By updating `uTime` in the `animate` loop, we create the animation effect.
4.  **Lighting:** While the shader handles the object's surface color, the `PointLight` interacts with the scene's depth and lighting model (if you were using standard materials like `MeshStandardMaterial`).

