            uniforms: { time: { value: 0 } },
            vertexShader: `
                varying vec3 vNormal;
                void main() {
                    vNormal = normal;
                    gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
                }`,
            fragmentShader: `
                uniform float time;
                varying vec3 vNormal;
                void main() {
                    // Dynamic color based on normal and time
                    vec3 color = 0.5 + 0.5 * cos(time + vNormal.xyx + vec3(0,2,4));
