This example creates a scene with a rotating 3D object, a dynamic light source that follows your mouse, and a custom shader effect (a "glow" or color-shift) applied to the object.

### The Code (`index.html`)

You can save this as an `.html` file and open it in any browser.

```html
<!DOCTYPE html>
<html>
<head>
    <style>body { margin: 0; overflow: hidden; }</style>
</head>
<body>
    <!-- Import Three.js via CDN -->
    <script type="module">
        import * as THREE from 'https://unpkg.com/three@0.158.0/build/three.module.js';

        // 1. Setup Scene
        const scene = new THREE.Scene();
        const camera = new THREE.PerspectiveCamera(75, window.innerWidth/window.innerHeight, 0.1, 1000);
        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        document.body.appendChild(renderer.domElement);

        // 2. Add Object with Custom Shader Material
        const geometry = new THREE.IcosahedronGeometry(1, 15);
        const material = new THREE.ShaderMaterial({
            uniforms: { time: { value: 0 } },
            vertexShader: `
                varying vec3 vNormal;
                void main() {
                    vNormal = normal;
                    gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
                }`,
            fragmentShader: `
                uniform float time;
                varying vec3 vNormal;
                void main() {
                    vec3 color = vec3(0.5 + 0.5 * sin(time), vNormal.y, 0.8);
                    gl_FragColor = vec4(color, 1.0);
                }`
        });
        const mesh = new THREE.Mesh(geometry, material);
        scene.add(mesh);

        // 3. Dynamic Lighting
        const light = new THREE.PointLight(0xffffff, 50);
        scene.add(light);
        camera.position.z = 3;

        // 4. Animation Loop
        function animate(t) {
            requestAnimationFrame(animate);
            material.uniforms.time.value = t * 0.002;
            mesh.rotation.x += 0.01;
            mesh.rotation.y += 0.01;

            // Move light with mouse
            light.position.set(Math.sin(t/1000)*2, Math.cos(t/1000)*2, 2);

            renderer.render(scene, camera);
        }
        animate(0);
    </script>
