```cpp
struct RigidBody {
    float mass;
    float inverseMass; // 0 for static objects
    glm::vec3 position;
    glm::vec3 velocity;
    glm::vec3 force;

    // Simple AABB for collision
    glm::vec3 minBound;
    glm::vec3 maxBound;

    void ApplyForce(const glm::vec3& f) {
        if (inverseMass > 0) force += f;
    }
};
```

### 2. The Physics World (The "Plugin" Core)
The plugin needs to manage the simulation loop. In a commercial engine, this would hook into the `Update` or `FixedUpdate` lifecycle.

```cpp
class PhysicsPlugin {
    std::vector<RigidBody*> bodies;

public:
    void Step(float deltaTime) {
        // 1. Integration (Update positions based on velocity)
        for (auto& body : bodies) {
            if (body->inverseMass == 0) continue;

            body->velocity += body->force * body->inverseMass * deltaTime;
            body->position += body->velocity * deltaTime;
            body->force = glm::vec3(0); // Reset forces
        }

        // 2. Collision Detection (Broadphase + Narrowphase)
        DetectCollisions();
    }

    void DetectCollisions() {
        for (size_t i = 0; i < bodies.size(); ++i) {
            for (size_t j = i + 1; j < bodies.size(); ++j) {
                if (CheckAABB(bodies[i], bodies[j])) {
                    ResolveCollision(bodies[i], bodies[j]);
                }
            }
        }
    }

    bool CheckAABB(RigidBody* a, RigidBody* b) {
        return (a->minBound.x <= b->maxBound.x && a->maxBound.x >= b->minBound.x) &&
               (a->minBound.y <= b->maxBound.y && a->maxBound.y >= b->minBound.y) &&
               (a->minBound.z <= b->maxBound.z && a->maxBound.z >= b->minBound.z);
    }

    void ResolveCollision(RigidBody* a, RigidBody* b) {
        // Simple impulse-based resolution
        glm::vec3 relativeVelocity = b->velocity - a->velocity;
        // ... Apply physics math (restitution, friction) here
    }
};
```

