#include "VortexPhysicsComponent.h"
#include "Engine/World.h"
#include "Components/PrimitiveComponent.h"

UVortexPhysicsComponent::UVortexPhysicsComponent()
{
    PrimaryComponentTick.bCanEverTick = true;
}

void UVortexPhysicsComponent::TickComponent(float DeltaTime, ELevelTick TickType, FActorComponentTickFunction* ThisTickFunction)
{
    Super::TickComponent(DeltaTime, TickType, ThisTickFunction);

    FVector Origin = GetComponentLocation();
    TArray<FOverlapResult> Overlaps;
    FCollisionShape SphereShape = FCollisionShape::MakeSphere(Radius);

    // Query the physics world for overlapping actors
    bool bHasOverlaps = GetWorld()->OverlapMultiByObjectType(
        Overlaps, 
        Origin, 
        FQuat::Identity, 
        FCollisionObjectQueryParams(ECollisionChannel::ECC_PhysicsBody), 
        SphereShape
    );

    if (bHasOverlaps)
    {
        for (const FOverlapResult& Result : Overlaps)
        {
            UPrimitiveComponent* PrimComp = Result.GetComponent();
            if (PrimComp && PrimComp->IsSimulatingPhysics())
            {
                // Apply a radial force towards the component location
                FVector Direction = (Origin - PrimComp->GetComponentLocation()).GetSafeNormal();
                PrimComp->AddForce(Direction * VortexStrength * PrimComp->GetMass());
            }
        }
    }
}
```

