### 1. The Physics Component (`PhysicsComponent.h`)
This component holds the state (position, velocity, mass) and is attached to game objects.

```cpp
#pragma once
#include <glm/glm.hpp> // Using GLM for math

struct PhysicsComponent {
    glm::vec3 position;
    glm::vec3 velocity;
    glm::vec3 force;
    float mass;
    float drag = 0.98f;

    PhysicsComponent(float m) : mass(m), position(0,0,0), velocity(0,0,0), force(0,0,0) {}

    void ApplyForce(glm::vec3 f) {
        force += f;
    }
};
```

### 2. The Physics Engine (`PhysicsWorld.h`)
This class manages the integration (Euler or Verlet) and updates all registered components.

```cpp
#include <vector>

class PhysicsWorld {
private:
    std::vector<PhysicsComponent*> bodies;
    glm::vec3 gravity = {0.0f, -9.81f, 0.0f};

public:
    void RegisterBody(PhysicsComponent* body) {
        bodies.push_back(body);
    }

    void Step(float deltaTime) {
        for (auto* body : bodies) {
            // F = ma -> a = F/m
            glm::vec3 acceleration = body->force / body->mass;
            acceleration += gravity;

            // Integrate velocity
            body->velocity += acceleration * deltaTime;
            body->velocity *= body->drag; // Simple air resistance

            // Integrate position
            body->position += body->velocity * deltaTime;

            // Reset forces for next frame
            body->force = glm::vec3(0.0f);
        }
    }
};
```

### 3. Integrating into a Game Loop
In a commercial engine, you would hook this into the engine's "Tick" or "Update" function.

```cpp
// Inside your Game Engine Main Loop
void OnUpdate(float deltaTime) {
    // 1. Update Physics
    physicsWorld.Step(deltaTime);

    // 2. Sync Physics state to Transform Component
    for (auto& entity : entities) {
        if (entity.hasComponent<PhysicsComponent>()) {
            auto& phys = entity.getComponent<PhysicsComponent>();
            entity.transform.position = phys.position;
        }
    }
}
```

