### 1. The Physics Object (Data)
We use `structs` to keep data in contiguous memory, which is better for cache performance.

```csharp
public struct PhysicsBody
{
    public Vector3 Position;
    public Vector3 Velocity;
    public Vector3 Force;
    public float Mass;
    public float InverseMass; // Precompute 1/mass for performance
}
```

### 2. The Physics World (The Solver)
This script acts as the "Engine" for your physics. It updates the positions manually.

```csharp
using UnityEngine;
using System.Collections.Generic;

public class CustomPhysicsWorld : MonoBehaviour
{
    public List<PhysicsBody> bodies = new List<PhysicsBody>();
    public Vector3 gravity = new Vector3(0, -9.81f, 0);

    void FixedUpdate()
    {
        float dt = Time.fixedDeltaTime;

        for (int i = 0; i < bodies.Count; i++)
        {
            PhysicsBody b = bodies[i];

            // 1. Apply Gravity
            b.Velocity += (gravity + (b.Force * b.InverseMass)) * dt;

            // 2. Integrate Position
            b.Position += b.Velocity * dt;

            // 3. Simple Floor Collision
            if (b.Position.y < 0)
            {
                b.Position.y = 0;
                b.Velocity.y *= -0.5f; // Bounce with damping
            }

            bodies[i] = b;
        }
    }
}
```

### 3. The Component (Bridge)
This is what you attach to GameObjects in the Editor. It registers the object with the `CustomPhysicsWorld`.

```csharp
public class CustomPhysicsComponent : MonoBehaviour
{
    public float mass = 1.0f;
    private int bodyIndex;

    void Start()
    {
        var world = FindObjectOfType<CustomPhysicsWorld>();
        var body = new PhysicsBody {
            Position = transform.position,
            Mass = mass,
            InverseMass = 1.0f / mass
        };

        world.bodies.Add(body);
        bodyIndex = world.bodies.Count - 1;
    }

    void LateUpdate()
    {
        // Sync the engine transform to our custom physics position
        var world = FindObjectOfType<CustomPhysicsWorld>();
        transform.position = world.bodies[bodyIndex].Position;
    }
}
