void PhysicsSystem::Update(std::vector<CustomPhysicsComponent>& bodies, float deltaTime) {
    const glm::vec3 gravity = {0.0f, -9.81f, 0.0f};

    for (auto& body : bodies) {
        // 1. Calculate Acceleration: F = ma -> a = F/m
        glm::vec3 acceleration = body.forceAccumulator / body.mass;

        if (body.useGravity) {
            acceleration += gravity;
        }

        // 2. Update Velocity
        body.velocity += acceleration * deltaTime;

        // 3. Update Position (This would be applied to the Transform)
        // Position += velocity * deltaTime;

        // 4. Reset Force Accumulator for next frame
        body.forceAccumulator = {0.0f, 0.0f, 0.0f};
    }
}
