### 1. The C++ Header (`gravity_modifier.h`)
This defines the object that will exist in the game world.

```cpp
#include <godot_cpp/classes/node3d.hpp>

namespace godot {
    class GravityModifier : public Node3D {
        GDCLASS(GravityModifier, Node3D)
    private:
        float gravity_strength = 9.8;
    protected:
        static void _bind_methods();
    public:
        void _physics_process(double delta) override;
        void set_strength(float p_strength);
    };
}
```

### 2. The C++ Implementation (`gravity_modifier.cpp`)
This is where the physics logic lives. We iterate through children and apply a downward force.

```cpp
#include "gravity_modifier.h"
#include <godot_cpp/classes/rigid_body3d.hpp>

using namespace godot;

void GravityModifier::_bind_methods() {
    ClassDB::bind_method(D_METHOD("set_strength", "strength"), &GravityModifier::set_strength);
}

void GravityModifier::_physics_process(double delta) {
    // Find all RigidBody3D children and apply custom gravity
    for (int i = 0; i < get_child_count(); i++) {
        RigidBody3D* rb = Object::cast_to<RigidBody3D>(get_child(i));
        if (rb) {
            rb->apply_central_force(Vector3(0, -gravity_strength * rb->get_mass(), 0));
        }
    }
}

void GravityModifier::set_strength(float p_strength) { gravity_strength = p_strength; }
```

### 3. The Registration (`register_types.cpp`)
Every plugin needs an entry point to tell the engine that your new node type exists.

