This example creates a simple **"Gravity-Defying" component** that you can attach to any object.

### 1. The C++ Header (`MyPhysics.hpp`)
This defines the interface for our custom physics object.

```cpp
#ifndef MY_PHYSICS_HPP
#define MY_PHYSICS_HPP

#include <godot_cpp/classes/node3d.hpp>

namespace godot {

class MyPhysicsBody : public Node3D {
    GDCLASS(MyPhysicsBody, Node3D)

protected:
    static void _bind_methods();

public:
    void _physics_process(double delta) override;
    float gravity_scale = 1.0;
};

}
#endif
```

### 2. The C++ Implementation (`MyPhysics.cpp`)
This contains the actual math logic. We manually manipulate the position to simulate physics.

```cpp
#include "MyPhysics.hpp"
#include <godot_cpp/variant/utility_functions.hpp>

using namespace godot;

void MyPhysicsBody::_bind_methods() {
    ClassDB::bind_method(D_METHOD("set_gravity", "val"), &MyPhysicsBody::gravity_scale);
}

void MyPhysicsBody::_physics_process(double delta) {
    // Basic custom physics: Apply velocity downward
    Vector3 pos = get_position();
    pos.y -= 9.8 * gravity_scale * delta;
    set_position(pos);
}
```

### 3. The Registration (`register_types.cpp`)
You must tell the engine that your new class exists.

```cpp
#include "register_types.h"
