async function processPayment(client, paymentData) {
    const { idempotencyKey, accountId, amount } = paymentData;

    try {
        await client.query('BEGIN');

        // 1. Check for Idempotency
        const existing = await client.query(
            'SELECT id FROM payments WHERE transaction_id = $1', [idempotencyKey]
        );
        if (existing.rows.length > 0) return existing.rows[0];

        // 2. Insert Payment
        const payment = await client.query(
            'INSERT INTO payments (id, transaction_id, account_id, amount) VALUES (gen_random_uuid(), $1, $2, $3) RETURNING *',
            [idempotencyKey, accountId, amount]
        );

        // 3. Insert into Outbox (The "Atomic" handoff)
        await client.query(
            'INSERT INTO outbox (aggregate_id, payload) VALUES ($1, $2)',
            [payment.rows[0].id, { type: 'PAYMENT_CREATED', data: payment.rows[0] }]
        );

        await client.query('COMMIT');
        return payment.rows[0];
    } catch (e) {
        await client.query('ROLLBACK');
        throw e;
    }
}
