```typescript
import Fastify from 'fastify';
import { z } from 'zod';

const fastify = Fastify({ logger: true });

// 1. Define strict schemas for input validation
const UserSchema = z.object({
  id: z.string().uuid(),
  email: z.string().email(),
  role: z.enum(['admin', 'user', 'guest']),
});

// 2. Define Type from Schema (Single Source of Truth)
type User = z.infer<typeof UserSchema>;

// 3. Mock Corporate Integration (e.g., Auth/Database)
const getCorporateUser = async (id: string): Promise<User> => {
  // In production, this calls your LDAP, Auth0, or internal DB
  return { id, email: 'dev@enterprise.com', role: 'admin' };
};

// 4. Route with strict validation
fastify.post<{ Body: { id: string } }>('/user/profile', async (request, reply) => {
  try {
    // Validate input at the boundary
    const validatedBody = z.object({ id: z.string().uuid() }).parse(request.body);

    // Process logic
    const user = await getCorporateUser(validatedBody.id);

    return { success: true, data: user };
  } catch (err) {
    if (err instanceof z.ZodError) {
      return reply.status(400).send({ error: 'Invalid schema', details: err.errors });
    }
    throw err;
  }
});

// 5. Start Server
const start = async () => {
  try {
    await fastify.listen({ port: 3000 });
  } catch (err) {
    fastify.log.error(err);
    process.exit(1);
  }
};
start();
```

### Why this fits Enterprise requirements:

1.  **Zod for Runtime Safety:** TypeScript types disappear at runtime. If an external system sends malformed JSON, `z.parse()` will catch it immediately, preventing "undefined is not a function" errors deep in your business logic.
2.  **Fastify:** Chosen over Express because it is significantly faster, has a lower memory footprint, and enforces a schema-based approach (via JSON Schema) which is standard for enterprise API documentation (OpenAPI/Swagger).
3.  **Single Source of Truth:** By using `z.infer`, your TypeScript interfaces are automatically generated from your validation schemas. You never have to manually sync an `interface` with a `validator` function.
4.  **Logging:** Uses `pino` (built into Fastify), which outputs JSON logs by default. This is critical for centralized logging systems like **Splunk, ELK Stack, or Datadog**.
5.  **Extensibility:** 
    *   **Auth:** You can easily add a `preHandler` hook to validate JWTs from your corporate Identity Provider (e.g., Okta/Azure AD).
    *   **Observability:** Fastify has plugins for OpenTelemetry, allowing you to trace requests across your microservice architecture.

