### 3. The Enterprise Guard (Validation Pipe)
We implement a custom pipe to ensure that any request hitting the controller is strictly validated against our schema before execution.

```typescript
// src/common/zod.pipe.ts
import { PipeTransform, BadRequestException } from '@nestjs/common';
import { ZodSchema } from 'zod';

export class ZodValidationPipe implements PipeTransform {
  constructor(private schema: ZodSchema) {}

  transform(value: unknown) {
    const result = this.schema.safeParse(value);
    if (!result.success) throw new BadRequestException(result.error.format());
    return result.data;
  }
}
```

