import Fastify, { FastifyInstance } from 'fastify';
import { z } from 'zod';

const server: FastifyInstance = Fastify({ logger: true });

// 1. Define strict schemas for corporate integration (Request/Response)
const UserRequestSchema = z.object({
  employeeId: z.string().uuid(),
  departmentCode: z.enum(['FINANCE', 'ENGINEERING', 'HR']),
});

// 2. Type definition derived from schema (Single Source of Truth)
type UserRequest = z.infer<typeof UserRequestSchema>;

// 3. Route with Zod validation
server.post<{ Body: UserRequest }>('/api/v1/resource', {
  schema: {
    body: {
      type: 'object',
      properties: {
        employeeId: { type: 'string', format: 'uuid' },
        departmentCode: { type: 'string', enum: ['FINANCE', 'ENGINEERING', 'HR'] }
      },
      required: ['employeeId', 'departmentCode']
    }
  }
}, async (request, reply) => {
  // Runtime validation
  const validation = UserRequestSchema.safeParse(request.body);

  if (!validation.success) {
    return reply.status(400).send({ error: 'Invalid Corporate Schema', details: validation.error });
  }

  // Business Logic
  return { status: 'PROCESSED', timestamp: new Date().toISOString() };
});

// 4. Start Server
const start = async () => {
  try {
    await server.listen({ port: 3000 });
  } catch (err) {
    server.log.error(err);
    process.exit(1);
  }
};

start();
```

